EMBEDDED_3D_HTML = '<!DOCTYPE html>\n<html lang="en">\n<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">\n  <title>AutoNav 3D // Smart Autonomous Vehicle Path Planner & Cockpit</title>\n  <link rel="preconnect" href="https://fonts.googleapis.com">\n  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&family=Orbitron:wght@500;700;800;900&family=JetBrains+Mono:wght@400;500;700&display=swap" rel="stylesheet">\n  \n  <script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>\n  <script src="https://cdn.jsdelivr.net/npm/three@0.128.0/examples/js/controls/OrbitControls.js"></script>\n  \n  <style>\n    :root {\n      --bg-dark: #080c14;\n      --panel-bg: rgba(13, 20, 36, 0.78);\n      --panel-border: rgba(0, 240, 255, 0.22);\n      --panel-hover: rgba(0, 240, 255, 0.4);\n      --cyan: #00f0ff;\n      --cyan-glow: rgba(0, 240, 255, 0.45);\n      --emerald: #00ff9d;\n      --amber: #ffaa00;\n      --red: #ff3366;\n      --purple: #9d4edd;\n      --text-main: #f0f4f8;\n      --text-muted: #8fa0b5;\n    }\n\n    * {\n      box-sizing: border-box;\n      margin: 0;\n      padding: 0;\n      user-select: none;\n    }\n\n    body, html {\n      width: 100%;\n      height: 100%;\n      overflow: hidden;\n      background: var(--bg-dark);\n      font-family: \'Inter\', -apple-system, BlinkMacSystemFont, sans-serif;\n      color: var(--text-main);\n    }\n\n    #canvas-container {\n      position: absolute;\n      top: 0;\n      left: 0;\n      width: 100%;\n      height: 100%;\n      z-index: 1;\n    }\n\n    /* Modern Glassmorphic UI Layer */\n    #ui-layer {\n      position: absolute;\n      top: 0;\n      left: 0;\n      width: 100%;\n      height: 100%;\n      z-index: 10;\n      pointer-events: none;\n      display: flex;\n      flex-direction: column;\n      justify-content: space-between;\n      padding: 16px 20px;\n    }\n\n    .interactive {\n      pointer-events: auto;\n    }\n\n    /* Glass Panels */\n    .glass-panel {\n      background: var(--panel-bg);\n      backdrop-filter: blur(16px);\n      -webkit-backdrop-filter: blur(16px);\n      border: 1px solid var(--panel-border);\n      border-radius: 14px;\n      box-shadow: 0 8px 32px rgba(0, 0, 0, 0.55), inset 0 1px 1px rgba(255, 255, 255, 0.1);\n      transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);\n    }\n\n    .glass-panel:hover {\n      border-color: var(--panel-hover);\n    }\n\n    /* Top Navigation Bar */\n    .header-bar {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 16px;\n      padding: 10px 18px;\n    }\n\n    .brand-section {\n      display: flex;\n      align-items: center;\n      gap: 12px;\n    }\n\n    .logo-badge {\n      width: 38px;\n      height: 38px;\n      border-radius: 10px;\n      background: linear-gradient(135deg, #00f0ff, #7928ca);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      font-size: 20px;\n      box-shadow: 0 0 16px var(--cyan-glow);\n    }\n\n    .brand-title {\n      font-family: \'Orbitron\', monospace;\n      font-size: 15px;\n      font-weight: 800;\n      letter-spacing: 1.5px;\n      background: linear-gradient(90deg, #ffffff, var(--cyan));\n      -webkit-background-clip: text;\n      -webkit-text-fill-color: transparent;\n      text-transform: uppercase;\n    }\n\n    .brand-sub {\n      font-size: 11px;\n      color: var(--text-muted);\n      letter-spacing: 0.5px;\n    }\n\n    /* Status Pill */\n    .status-pill {\n      display: flex;\n      align-items: center;\n      gap: 8px;\n      padding: 6px 14px;\n      border-radius: 30px;\n      background: rgba(0, 240, 255, 0.1);\n      border: 1px solid rgba(0, 240, 255, 0.3);\n      font-family: \'Orbitron\', sans-serif;\n      font-size: 12px;\n      font-weight: 700;\n      letter-spacing: 1px;\n    }\n\n    .status-dot {\n      width: 8px;\n      height: 8px;\n      border-radius: 50%;\n      background: var(--cyan);\n      box-shadow: 0 0 10px var(--cyan);\n      animation: pulse 1.5s infinite;\n    }\n\n    @keyframes pulse {\n      0%, 100% { opacity: 1; transform: scale(1); }\n      50% { opacity: 0.4; transform: scale(0.85); }\n    }\n\n    /* Segmented Camera & Controls */\n    .camera-switcher {\n      display: flex;\n      background: rgba(8, 14, 26, 0.7);\n      padding: 4px;\n      border-radius: 12px;\n      border: 1px solid rgba(255, 255, 255, 0.08);\n      gap: 4px;\n    }\n\n    .cam-btn {\n      background: transparent;\n      border: none;\n      color: var(--text-muted);\n      padding: 7px 13px;\n      border-radius: 8px;\n      font-size: 12px;\n      font-weight: 600;\n      cursor: pointer;\n      display: flex;\n      align-items: center;\n      gap: 6px;\n      transition: all 0.2s ease;\n      font-family: \'Inter\', sans-serif;\n    }\n\n    .cam-btn:hover {\n      color: #fff;\n      background: rgba(255, 255, 255, 0.06);\n    }\n\n    .cam-btn.active {\n      background: linear-gradient(135deg, rgba(0, 240, 255, 0.25), rgba(121, 40, 202, 0.35));\n      border: 1px solid var(--cyan);\n      color: #fff;\n      box-shadow: 0 0 14px rgba(0, 240, 255, 0.3);\n    }\n\n    .quick-actions {\n      display: flex;\n      align-items: center;\n      gap: 8px;\n    }\n\n    .icon-btn {\n      background: rgba(255, 255, 255, 0.05);\n      border: 1px solid rgba(255, 255, 255, 0.1);\n      color: var(--text-main);\n      width: 36px;\n      height: 36px;\n      border-radius: 10px;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      cursor: pointer;\n      font-size: 15px;\n      transition: all 0.2s;\n    }\n\n    .icon-btn:hover {\n      background: rgba(0, 240, 255, 0.15);\n      border-color: var(--cyan);\n      box-shadow: 0 0 10px var(--cyan-glow);\n    }\n\n    /* Middle Layout */\n    .middle-area {\n      display: flex;\n      justify-content: space-between;\n      align-items: flex-start;\n      margin: 12px 0;\n      flex: 1;\n      pointer-events: none;\n    }\n\n    /* Left Sidebar: Path Planning & World Setup */\n    .left-card {\n      width: 320px;\n      padding: 16px;\n      display: flex;\n      flex-direction: column;\n      gap: 14px;\n      pointer-events: auto;\n    }\n\n    .section-title {\n      font-family: \'Orbitron\', sans-serif;\n      font-size: 11px;\n      font-weight: 700;\n      text-transform: uppercase;\n      letter-spacing: 1.2px;\n      color: var(--cyan);\n      display: flex;\n      align-items: center;\n      gap: 8px;\n    }\n\n    .paths-container {\n      display: flex;\n      flex-direction: column;\n      gap: 8px;\n    }\n\n    .path-card {\n      background: rgba(17, 27, 46, 0.6);\n      border: 1px solid rgba(255, 255, 255, 0.08);\n      border-radius: 10px;\n      padding: 10px 12px;\n      cursor: pointer;\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      transition: all 0.2s;\n    }\n\n    .path-card:hover {\n      border-color: rgba(0, 240, 255, 0.4);\n      background: rgba(0, 240, 255, 0.06);\n    }\n\n    .path-card.selected {\n      border-color: var(--cyan);\n      background: linear-gradient(90deg, rgba(0, 240, 255, 0.15), rgba(0, 240, 255, 0.02));\n      box-shadow: 0 0 12px rgba(0, 240, 255, 0.2);\n    }\n\n    .path-info {\n      display: flex;\n      flex-direction: column;\n      gap: 2px;\n    }\n\n    .path-name {\n      font-family: \'Orbitron\', monospace;\n      font-size: 13px;\n      font-weight: 700;\n      color: #fff;\n    }\n\n    .path-meta {\n      font-size: 11px;\n      color: var(--text-muted);\n    }\n\n    .badge-clear {\n      font-size: 10px;\n      padding: 3px 8px;\n      border-radius: 20px;\n      background: rgba(0, 255, 157, 0.15);\n      border: 1px solid var(--emerald);\n      color: var(--emerald);\n      font-weight: 700;\n    }\n\n    .badge-blocked {\n      font-size: 10px;\n      padding: 3px 8px;\n      border-radius: 20px;\n      background: rgba(255, 51, 102, 0.15);\n      border: 1px solid var(--red);\n      color: var(--red);\n      font-weight: 700;\n    }\n\n    /* Right Sidebar: Obstacle Spawner */\n    .right-card {\n      width: 320px;\n      padding: 16px;\n      display: flex;\n      flex-direction: column;\n      gap: 14px;\n      pointer-events: auto;\n    }\n\n    .spawner-grid {\n      display: grid;\n      grid-template-columns: repeat(3, 1fr);\n      gap: 8px;\n    }\n\n    .spawner-item {\n      background: rgba(17, 27, 46, 0.6);\n      border: 1px solid rgba(255, 255, 255, 0.08);\n      border-radius: 10px;\n      padding: 10px 6px;\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      gap: 6px;\n      cursor: pointer;\n      transition: all 0.2s;\n    }\n\n    .spawner-item:hover {\n      border-color: var(--cyan);\n      background: rgba(0, 240, 255, 0.08);\n    }\n\n    .spawner-item.active {\n      border-color: var(--cyan);\n      background: rgba(0, 240, 255, 0.2);\n      box-shadow: 0 0 12px rgba(0, 240, 255, 0.25);\n    }\n\n    .spawner-emoji {\n      font-size: 22px;\n    }\n\n    .spawner-label {\n      font-size: 10px;\n      font-weight: 600;\n      color: var(--text-main);\n      text-align: center;\n    }\n\n    .motion-toggle {\n      display: flex;\n      background: rgba(8, 14, 26, 0.7);\n      padding: 3px;\n      border-radius: 8px;\n      gap: 3px;\n    }\n\n    .motion-btn {\n      flex: 1;\n      padding: 6px 4px;\n      background: transparent;\n      border: none;\n      color: var(--text-muted);\n      border-radius: 6px;\n      font-size: 11px;\n      font-weight: 600;\n      cursor: pointer;\n      transition: all 0.2s;\n      text-align: center;\n    }\n\n    .motion-btn.active {\n      background: rgba(0, 240, 255, 0.2);\n      color: #fff;\n      border: 1px solid var(--cyan);\n    }\n\n    .click-tip {\n      font-size: 11px;\n      color: var(--cyan);\n      background: rgba(0, 240, 255, 0.08);\n      border: 1px dashed rgba(0, 240, 255, 0.3);\n      padding: 8px 10px;\n      border-radius: 8px;\n      text-align: center;\n      line-height: 1.4;\n    }\n\n    /* Bottom Dock: Driving Controls & Telemetry */\n    .bottom-dock {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 16px;\n      padding: 12px 20px;\n    }\n\n    .main-controls {\n      display: flex;\n      align-items: center;\n      gap: 10px;\n    }\n\n    \n    \n    /* Mode Switcher */\n    .mode-switcher {\n      display: flex;\n      background: rgba(8, 14, 26, 0.75);\n      padding: 4px;\n      border-radius: 12px;\n      border: 1px solid rgba(0, 240, 255, 0.3);\n      gap: 4px;\n    }\n    .mode-btn {\n      background: transparent;\n      border: none;\n      color: var(--text-muted);\n      padding: 7px 14px;\n      border-radius: 8px;\n      font-size: 12px;\n      font-weight: 700;\n      cursor: pointer;\n      display: flex;\n      align-items: center;\n      gap: 6px;\n      transition: all 0.2s;\n      font-family: \'Orbitron\', sans-serif;\n    }\n    .mode-btn.active {\n      background: linear-gradient(135deg, rgba(0, 240, 255, 0.35), rgba(0, 119, 255, 0.45));\n      border: 1px solid var(--cyan);\n      color: #fff;\n      box-shadow: 0 0 14px rgba(0, 240, 255, 0.4);\n    }\n\n    /* On-Screen Manual Drive Pedals & Steer */\n    #manual-controls-dock {\n      position: absolute;\n      bottom: 85px;\n      right: 25px;\n      display: flex;\n      gap: 16px;\n      z-index: 18;\n      pointer-events: auto;\n      transition: opacity 0.3s, transform 0.3s;\n    }\n    #manual-controls-dock.hidden {\n      opacity: 0;\n      pointer-events: none;\n      transform: translateY(20px);\n    }\n    .d-pad {\n      display: grid;\n      grid-template-columns: repeat(3, 44px);\n      grid-template-rows: repeat(2, 44px);\n      gap: 6px;\n    }\n    .d-btn {\n      background: rgba(13, 20, 36, 0.85);\n      border: 1px solid var(--cyan);\n      color: var(--cyan);\n      border-radius: 10px;\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      font-size: 16px;\n      font-weight: bold;\n      cursor: pointer;\n      box-shadow: 0 0 10px rgba(0, 240, 255, 0.2);\n      user-select: none;\n      transition: all 0.1s;\n    }\n    .d-btn:active, .d-btn.pressed {\n      background: var(--cyan);\n      color: #040914;\n      box-shadow: 0 0 20px var(--cyan);\n      transform: scale(0.94);\n    }\n    .pedal-box {\n      display: flex;\n      gap: 8px;\n    }\n    .pedal-btn {\n      width: 52px;\n      height: 94px;\n      border-radius: 12px;\n      border: 2px solid var(--cyan);\n      background: rgba(13, 20, 36, 0.85);\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      justify-content: center;\n      gap: 4px;\n      cursor: pointer;\n      font-family: \'Orbitron\', sans-serif;\n      font-size: 10px;\n      font-weight: bold;\n      color: #fff;\n      box-shadow: 0 0 15px rgba(0, 240, 255, 0.25);\n      transition: all 0.1s;\n    }\n    .pedal-btn.gas {\n      border-color: var(--emerald);\n      color: var(--emerald);\n    }\n    .pedal-btn.gas:active, .pedal-btn.gas.pressed {\n      background: var(--emerald);\n      color: #040914;\n      box-shadow: 0 0 25px var(--emerald);\n      transform: translateY(4px);\n    }\n    .pedal-btn.brake {\n      border-color: var(--red);\n      color: var(--red);\n    }\n    .pedal-btn.brake:active, .pedal-btn.brake.pressed {\n      background: var(--red);\n      color: #fff;\n      box-shadow: 0 0 25px var(--red);\n      transform: translateY(4px);\n    }\n\n    /* Blockage Alert Banner */\n    #block-alert-banner {\n      position: absolute;\n      top: 76px;\n      left: 50%;\n      transform: translateX(-50%);\n      background: rgba(255, 51, 102, 0.92);\n      border: 1px solid #ffffff;\n      color: #ffffff;\n      padding: 10px 24px;\n      border-radius: 30px;\n      font-family: \'Orbitron\', sans-serif;\n      font-size: 13px;\n      font-weight: 700;\n      display: flex;\n      align-items: center;\n      gap: 12px;\n      box-shadow: 0 0 30px rgba(255, 51, 102, 0.7);\n      z-index: 22;\n      opacity: 0;\n      pointer-events: none;\n      transition: all 0.3s;\n    }\n    #block-alert-banner.show {\n      opacity: 1;\n      pointer-events: auto;\n      transform: translateX(-50%) translateY(4px);\n    }\n    .banner-clear-btn {\n      background: #ffffff;\n      color: #ff3366;\n      border: none;\n      border-radius: 16px;\n      padding: 4px 12px;\n      font-size: 11px;\n      font-weight: 800;\n      cursor: pointer;\n    }\n\n    /* Top Bar Start Button */\n    .top-start-btn {\n      background: linear-gradient(135deg, #00f0ff, #0077ff);\n      color: #040914;\n      border: none;\n      border-radius: 10px;\n      padding: 8px 18px;\n      font-family: \'Orbitron\', sans-serif;\n      font-size: 13px;\n      font-weight: 800;\n      letter-spacing: 1px;\n      cursor: pointer;\n      display: flex;\n      align-items: center;\n      gap: 6px;\n      box-shadow: 0 0 16px rgba(0, 240, 255, 0.6);\n      animation: glowPulse 2s infinite ease-in-out;\n      transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);\n    }\n    .top-start-btn:hover {\n      transform: scale(1.06);\n      box-shadow: 0 0 26px rgba(0, 240, 255, 0.9);\n    }\n    .top-start-btn.stopped {\n      background: linear-gradient(135deg, #ff3366, #ff7700);\n      color: #fff;\n      box-shadow: 0 0 16px rgba(255, 51, 102, 0.5);\n      animation: none;\n    }\n    @keyframes glowPulse {\n      0%, 100% { box-shadow: 0 0 12px rgba(0, 240, 255, 0.4); transform: scale(1); }\n      50% { box-shadow: 0 0 25px rgba(0, 240, 255, 0.95); transform: scale(1.03); }\n    }\n\n    /* Big Center Ignition Card */\n    #center-ignition-card {\n      position: absolute;\n      top: 50%;\n      left: 50%;\n      transform: translate(-50%, -50%);\n      background: rgba(10, 16, 30, 0.88);\n      backdrop-filter: blur(20px);\n      -webkit-backdrop-filter: blur(20px);\n      border: 2px solid var(--cyan);\n      border-radius: 24px;\n      padding: 24px 40px;\n      display: flex;\n      flex-direction: column;\n      align-items: center;\n      gap: 12px;\n      cursor: pointer;\n      box-shadow: 0 0 50px rgba(0, 240, 255, 0.5), inset 0 0 24px rgba(0, 240, 255, 0.2);\n      z-index: 25;\n      transition: all 0.3s cubic-bezier(0.16, 1, 0.3, 1);\n      animation: ignitionPulse 2s infinite ease-in-out;\n      pointer-events: auto;\n    }\n    #center-ignition-card:hover {\n      transform: translate(-50%, -50%) scale(1.08);\n      box-shadow: 0 0 75px rgba(0, 240, 255, 0.9);\n      border-color: #ffffff;\n    }\n    #center-ignition-card.hidden {\n      opacity: 0;\n      pointer-events: none;\n      transform: translate(-50%, -50%) scale(0.85);\n    }\n    .ignition-icon {\n      font-size: 38px;\n      width: 64px;\n      height: 64px;\n      border-radius: 50%;\n      background: linear-gradient(135deg, #00f0ff, #7928ca);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n      box-shadow: 0 0 24px var(--cyan);\n    }\n    .ignition-title {\n      font-family: \'Orbitron\', monospace;\n      font-size: 22px;\n      font-weight: 900;\n      letter-spacing: 2px;\n      color: #ffffff;\n      text-shadow: 0 0 12px rgba(0, 240, 255, 0.8);\n    }\n    .ignition-sub {\n      font-size: 12px;\n      color: var(--text-muted);\n      letter-spacing: 0.5px;\n    }\n    @keyframes ignitionPulse {\n      0%, 100% { box-shadow: 0 0 35px rgba(0, 240, 255, 0.45); }\n      50% { box-shadow: 0 0 65px rgba(0, 240, 255, 0.9); }\n    }\n\n    .drive-btn {\n      background: linear-gradient(135deg, #00f0ff, #0077ff);\n      color: #040914;\n      border: none;\n      border-radius: 12px;\n      padding: 12px 26px;\n      font-family: \'Orbitron\', sans-serif;\n      font-size: 14px;\n      font-weight: 800;\n      letter-spacing: 1px;\n      cursor: pointer;\n      display: flex;\n      align-items: center;\n      gap: 8px;\n      box-shadow: 0 0 20px rgba(0, 240, 255, 0.4);\n      transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);\n    }\n\n    .drive-btn:hover {\n      transform: translateY(-2px);\n      box-shadow: 0 0 28px rgba(0, 240, 255, 0.6);\n    }\n\n    .drive-btn:active {\n      transform: translateY(0);\n    }\n\n    .drive-btn.stopped {\n      background: linear-gradient(135deg, #ff3366, #ff7700);\n      color: #fff;\n      box-shadow: 0 0 20px rgba(255, 51, 102, 0.4);\n    }\n\n    .telemetry-row {\n      display: flex;\n      align-items: center;\n      gap: 24px;\n    }\n\n    .telemetry-item {\n      display: flex;\n      flex-direction: column;\n      gap: 2px;\n      min-width: 75px;\n    }\n\n    .telemetry-label {\n      font-size: 10px;\n      font-weight: 600;\n      color: var(--text-muted);\n      text-transform: uppercase;\n      letter-spacing: 0.8px;\n    }\n\n    .telemetry-val {\n      font-family: \'Orbitron\', monospace;\n      font-size: 18px;\n      font-weight: 800;\n      color: #fff;\n      display: flex;\n      align-items: baseline;\n      gap: 4px;\n    }\n\n    .telemetry-unit {\n      font-size: 11px;\n      color: var(--cyan);\n      font-weight: 500;\n    }\n\n    /* Road Progress Bar */\n    .road-progress-box {\n      width: 220px;\n      display: flex;\n      flex-direction: column;\n      gap: 6px;\n    }\n\n    .progress-track {\n      width: 100%;\n      height: 8px;\n      background: rgba(255, 255, 255, 0.1);\n      border-radius: 4px;\n      overflow: hidden;\n      position: relative;\n    }\n\n    .progress-fill {\n      height: 100%;\n      width: 0%;\n      background: linear-gradient(90deg, var(--cyan), var(--emerald));\n      border-radius: 4px;\n      box-shadow: 0 0 10px var(--cyan);\n      transition: width 0.1s linear;\n    }\n\n    /* Cockpit Specific HUD Canvas Overlay */\n    #cockpit-hud {\n      position: absolute;\n      top: 0;\n      left: 0;\n      width: 100%;\n      height: 100%;\n      pointer-events: none;\n      z-index: 5;\n      display: none;\n    }\n\n    /* Cockpit Windshield Vignette & Frame */\n    .cockpit-overlay {\n      position: absolute;\n      top: 0;\n      left: 0;\n      width: 100%;\n      height: 100%;\n      pointer-events: none;\n      z-index: 4;\n      display: none;\n      box-shadow: inset 0 0 100px rgba(0, 0, 0, 0.8);\n      background: radial-gradient(circle at 50% 40%, transparent 60%, rgba(5, 10, 20, 0.85) 100%);\n    }\n\n    .cockpit-overlay::before {\n      content: \'\';\n      position: absolute;\n      top: 0;\n      left: 0;\n      width: 100%;\n      height: 40px;\n      background: linear-gradient(to bottom, rgba(5, 10, 20, 0.95), transparent);\n    }\n\n    /* Warning Overlay */\n    #warning-strobe {\n      position: absolute;\n      top: 0;\n      left: 0;\n      width: 100%;\n      height: 100%;\n      pointer-events: none;\n      z-index: 6;\n      border: 4px solid var(--red);\n      opacity: 0;\n      transition: opacity 0.2s;\n      box-shadow: inset 0 0 50px rgba(255, 51, 102, 0.5);\n    }\n\n    /* Mini Toast */\n    #toast-msg {\n      position: absolute;\n      top: 80px;\n      left: 50%;\n      transform: translateX(-50%);\n      background: rgba(13, 20, 36, 0.9);\n      border: 1px solid var(--cyan);\n      color: #fff;\n      padding: 10px 20px;\n      border-radius: 30px;\n      font-size: 13px;\n      font-weight: 600;\n      box-shadow: 0 0 20px var(--cyan-glow);\n      opacity: 0;\n      transition: opacity 0.3s, transform 0.3s;\n      z-index: 20;\n      pointer-events: none;\n    }\n\n    #toast-msg.show {\n      opacity: 1;\n      transform: translateX(-50%) translateY(10px);\n    }\n  </style>\n</head>\n<body>\n\n  <div id="canvas-container"></div>\n  <canvas id="cockpit-hud"></canvas>\n  <div class="cockpit-overlay" id="cockpit-overlay"></div>\n  <div id="warning-strobe"></div>\n  <div id="toast-msg">Notification</div>\n\n  <div id="ui-layer">\n    <!-- Top Header -->\n    <header class="header-bar glass-panel interactive">\n      <div class="brand-section">\n        <div class="logo-badge">🏎️</div>\n        <div>\n          <div class="brand-title">AUTONAV // 3D</div>\n          <div class="brand-sub">Neural Autonomous Path Planner & Cockpit Simulator</div>\n        </div>\n      </div>\n\n      <div class="status-pill" id="status-pill">\n        <div class="status-dot" id="status-dot"></div>\n        <span id="status-text">AUTOPILOT READY</span>\n      </div>\n\n      <!-- Prominent Top Start Button -->\n      <button class="top-start-btn interactive" id="btn-top-drive" onclick="startDriving3D()" style="background: linear-gradient(135deg, #00f0ff, #0077ff);">\n        ▶ Start driving\n      </button>\n\n      <!-- Camera switcher -->\n      <div class="camera-switcher">\n        <button class="cam-btn active" id="btn-cam-cockpit" onclick="setCameraMode(\'cockpit\')">\n          🏎️ Cockpit (FPV)\n        </button>\n        <button class="cam-btn" id="btn-cam-chase" onclick="setCameraMode(\'chase\')">\n          🎥 Chase Cam\n        </button>\n        <button class="cam-btn" id="btn-cam-drone" onclick="setCameraMode(\'drone\')">\n          🚁 Drone 3D\n        </button>\n        <button class="cam-btn" id="btn-cam-orbit" onclick="setCameraMode(\'orbit\')">\n          🌐 Orbit 3D\n        </button>\n        <button class="cam-btn" id="btn-cam-tactical" onclick="setCameraMode(\'tactical\')">\n          🗺️ Tactical 2D\n        </button>\n      </div>\n\n      <!-- Quick Actions -->\n      <div class="quick-actions">\n        <button class="icon-btn" title="Toggle Lighting (Night / Sunset / Day)" onclick="toggleEnvironment()">\n          <span id="env-icon">🌃</span>\n        </button>\n        <button class="icon-btn" title="Audio Sound FX" onclick="toggleAudio()">\n          <span id="sound-icon">🔊</span>\n        </button>\n        <button class="icon-btn" title="Reset View" onclick="resetCameraOrientation()">\n          🎯\n        </button>\n      </div>\n    </header>\n\n    <!-- Middle Working Area -->\n    <div class="middle-area">\n      <!-- Left Panel: Paths -->\n      <aside class="left-card glass-panel interactive">\n        <div class="section-title">\n          <span>🛣️ Planned Trajectories</span>\n          <span style="margin-left: auto; font-size: 10px; color: var(--text-muted);" id="path-count-lbl">3 PATHS</span>\n        </div>\n\n        <div style="display: flex; gap: 6px; align-items: center; font-size: 12px; color: var(--text-muted);">\n          <span>Candidates:</span>\n          <input type="range" min="1" max="5" value="3" id="path-slider" style="flex:1;" oninput="updatePathCount(this.value)">\n          <span id="path-slider-val" style="font-family:\'Orbitron\'; font-weight:700; color:#fff;">3</span>\n        </div>\n\n        <div class="paths-container" id="paths-list">\n          <!-- Dynamically populated -->\n        </div>\n\n        <div style="font-size: 11px; color: var(--text-muted); line-height: 1.4; border-top: 1px solid rgba(255,255,255,0.08); padding-top: 8px;">\n          Dynamic time-aware A* evaluates obstacle velocity vectors and re-routes seamlessly when moving obstacles intersect the path.\n        </div>\n      </aside>\n\n      <!-- Right Panel: Obstacle Spawner -->\n      <aside class="right-card glass-panel interactive">\n        <div class="section-title">\n          <span>⚠️ Obstacle Spawner</span>\n          <span style="margin-left: auto; font-size: 10px; color: var(--amber);" id="obs-count-badge">0 PLACED</span>\n        </div>\n\n        <div class="spawner-grid">\n          <div class="spawner-item active" onclick="selectObstacle(\'🧍 Pedestrian\', this)">\n            <span class="spawner-emoji">🧍</span>\n            <span class="spawner-label">Pedestrian</span>\n          </div>\n          <div class="spawner-item" onclick="selectObstacle(\'🐄 Cow\', this)">\n            <span class="spawner-emoji">🐄</span>\n            <span class="spawner-label">Cow</span>\n          </div>\n          <div class="spawner-item" onclick="selectObstacle(\'🛒 Pushcart\', this)">\n            <span class="spawner-emoji">🛒</span>\n            <span class="spawner-label">Pushcart</span>\n          </div>\n          <div class="spawner-item" onclick="selectObstacle(\'🚗 Vehicle\', this)">\n            <span class="spawner-emoji">🚗</span>\n            <span class="spawner-label">Vehicle</span>\n          </div>\n          <div class="spawner-item" onclick="selectObstacle(\'🕳️ Pothole\', this)">\n            <span class="spawner-emoji">🕳️</span>\n            <span class="spawner-label">Pothole</span>\n          </div>\n          <div class="spawner-item" onclick="randomizeObstacles()" title="Randomize World Obstacles">\n            <span class="spawner-emoji">🎲</span>\n            <span class="spawner-label">Randomize</span>\n          </div>\n        </div>\n\n        <div class="section-title" style="margin-top: 4px;">Motion Trajectory</div>\n        <div class="motion-toggle">\n          <button class="motion-btn active" onclick="selectMotion(\'Static\', this)">Static</button>\n          <button class="motion-btn" onclick="selectMotion(\'Crossing the road\', this)">Crossing</button>\n          <button class="motion-btn" onclick="selectMotion(\'Moving ahead\', this)">Moving Ahead</button>\n        </div>\n\n        <div class="click-tip">\n          👆 <strong>Click anywhere on the 3D road</strong> to drop obstacles while driving! The car predicts their movement and steers around them.\n        </div>\n\n        <div style="display: flex; gap: 8px;">\n          <button class="icon-btn" style="flex: 1; height: 32px; font-size: 12px; border-radius: 8px;" onclick="undoLastObstacle()">\n            ↩️ Undo\n          </button>\n          <button class="icon-btn" style="flex: 1; height: 32px; font-size: 12px; border-radius: 8px;" onclick="clearAllObstacles()">\n            🗑️ Clear All\n          </button>\n        </div>\n      </aside>\n    </div>\n\n    <!-- Bottom Dock -->\n    <footer class="bottom-dock glass-panel interactive">\n      <div class="main-controls">\n        <button class="drive-btn" id="btn-drive" onclick="startDriving3D()">\n          ▶ Start driving\n        </button>\n        <button class="icon-btn" title="Reset Simulation" onclick="resetSimulation()" style="width: 44px; height: 44px;">\n          ⏹\n        </button>\n        <div style="display: flex; flex-direction: column; gap: 2px; margin-left: 6px;">\n          <span style="font-size: 10px; color: var(--text-muted); font-weight: 600;">SIM SPEED</span>\n          <div class="motion-toggle" style="padding: 2px;">\n            <button class="motion-btn" id="spd-slow" onclick="setSpeed(\'Slow\', this)">0.5x</button>\n            <button class="motion-btn active" id="spd-norm" onclick="setSpeed(\'Normal\', this)">1.0x</button>\n            <button class="motion-btn" id="spd-fast" onclick="setSpeed(\'Fast\', this)">2.0x</button>\n          </div>\n        </div>\n      </div>\n\n      <!-- Telemetry Info -->\n      <div class="telemetry-row">\n        <div class="telemetry-item">\n          <span class="telemetry-label">SPEED</span>\n          <div class="telemetry-val"><span id="tel-speed">0.0</span> <span class="telemetry-unit">m/s</span></div>\n        </div>\n\n        <div class="telemetry-item">\n          <span class="telemetry-label">STEER</span>\n          <div class="telemetry-val"><span id="tel-steer">0.0</span> <span class="telemetry-unit">°</span></div>\n        </div>\n\n        <div class="telemetry-item">\n          <span class="telemetry-label">REPLANS</span>\n          <div class="telemetry-val" style="color: var(--cyan);"><span id="tel-replans">0</span></div>\n        </div>\n\n        <div class="telemetry-item">\n          <span class="telemetry-label">DISTANCE</span>\n          <div class="telemetry-val"><span id="tel-dist">0.0</span> <span class="telemetry-unit">/ 40m</span></div>\n        </div>\n\n        <div class="road-progress-box">\n          <div style="display: flex; justify-content: space-between; font-size: 10px; color: var(--text-muted); font-weight: 600;">\n            <span>START (0m)</span>\n            <span id="tel-pct">0%</span>\n            <span>GOAL (40m)</span>\n          </div>\n          <div class="progress-track">\n            <div class="progress-fill" id="progress-fill"></div>\n          </div>\n        </div>\n      </div>\n    </footer>\n  </div>\n\n  <script>\n    /* =========================================================================\n       1. CONSTANTS & PHYSICAL MODEL (Matching the Smart Vehicle Path Planner)\n       ========================================================================= */\n    const ROAD_HALF = 6.0;      // meters (-6m to +6m)\n    const X_END = 40.0;         // meters (0m to 40m)\n    const VEH_LEN = 4.2;        // vehicle length\n    const HALF_W = 0.9;         // vehicle half-width\n    const RES = 0.25;           // spatial resolution grid (m)\n    const DT = 0.05;            // simulation tick rate (seconds)\n    const HX0 = VEH_LEN / 2, HY0 = HALF_W;\n    const HX = HX0 + 0.5, HY = HY0 + 0.6;\n    const VX = HX0 + 0.3, VY = HY0 + 0.4;\n    const LIM = ROAD_HALF - 0.8;\n    const V_NOM = 2.5;\n\n    // Obstacle types: [length, width, speed m/s, color, 3d shape type]\n    const OBJ_PROPS = {\n      "🧍 Pedestrian": { L: 0.8, W: 0.8, spd: 1.2, color: 0x38bdf8, emoji: "🧍" },\n      "🐄 Cow":        { L: 2.0, W: 0.9, spd: 0.7, color: 0xfacc15, emoji: "🐄" },\n      "🛒 Pushcart":   { L: 1.6, W: 1.0, spd: 0.9, color: 0xf97316, emoji: "🛒" },\n      "🚗 Vehicle":    { L: 4.2, W: 1.8, spd: 1.5, color: 0xec4899, emoji: "🚗" },\n      "🕳️ Pothole":    { L: 1.2, W: 1.2, spd: 0.0, color: 0x64748b, emoji: "🕳️" },\n    };\n\n    // Precomputed grid arrays\n    const XS = [];\n    for (let x = 0; x <= X_END + 0.001; x += RES) XS.push(parseFloat(x.toFixed(3)));\n    const YS = [];\n    for (let y = -ROAD_HALF; y <= ROAD_HALF + 0.001; y += RES) YS.push(parseFloat(y.toFixed(3)));\n\n    /* =========================================================================\n       2. THREE.JS SCENE SETUP\n       ========================================================================= */\n    const container = document.getElementById(\'canvas-container\');\n    const scene = new THREE.Scene();\n    scene.background = new THREE.Color(0x060913);\n    scene.fog = new THREE.FogExp2(0x060913, 0.015);\n\n    const camera = new THREE.PerspectiveCamera(65, window.innerWidth / window.innerHeight, 0.1, 1000);\n    const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: "high-performance" });\n    renderer.setSize(window.innerWidth, window.innerHeight);\n    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));\n    renderer.shadowMap.enabled = true;\n    renderer.shadowMap.type = THREE.PCFSoftShadowMap;\n    renderer.toneMapping = THREE.ACESFilmicToneMapping;\n    renderer.toneMappingExposure = 1.1;\n    container.appendChild(renderer.domElement);\n\n    const controls = new THREE.OrbitControls(camera, renderer.domElement);\n    controls.enableDamping = true;\n    controls.dampingFactor = 0.05;\n    controls.maxPolarAngle = Math.PI / 2 - 0.02; // Don\'t go below ground\n    controls.minDistance = 2;\n    controls.maxDistance = 80;\n\n    // Cockpit 2D Canvas Overlay\n    const hudCanvas = document.getElementById(\'cockpit-hud\');\n    const hudCtx = hudCanvas.getContext(\'2d\');\n    function resizeHud() {\n      hudCanvas.width = window.innerWidth;\n      hudCanvas.height = window.innerHeight;\n    }\n    resizeHud();\n\n    // Lighting\n    const ambientLight = new THREE.AmbientLight(0x2a3b5c, 0.9);\n    scene.add(ambientLight);\n\n    const dirLight = new THREE.DirectionalLight(0x8bc34a, 0.8);\n    dirLight.position.set(20, 40, -30);\n    dirLight.castShadow = true;\n    dirLight.shadow.mapSize.width = 2048;\n    dirLight.shadow.mapSize.height = 2048;\n    dirLight.shadow.camera.near = 0.5;\n    dirLight.shadow.camera.far = 120;\n    dirLight.shadow.camera.left = -30;\n    dirLight.shadow.camera.right = 50;\n    dirLight.shadow.camera.top = 20;\n    dirLight.shadow.camera.bottom = -20;\n    scene.add(dirLight);\n\n    // Environment Presets: Night, Sunset, Day\n    let currentEnv = \'night\';\n    function setEnvironment(env) {\n      currentEnv = env;\n      if (env === \'night\') {\n        scene.background.set(0x060913);\n        scene.fog.color.set(0x060913);\n        ambientLight.color.set(0x1a2844);\n        ambientLight.intensity = 0.8;\n        dirLight.color.set(0x38bdf8);\n        dirLight.intensity = 0.4;\n        document.getElementById(\'env-icon\').innerText = \'🌃\';\n      } else if (env === \'sunset\') {\n        scene.background.set(0x1e1026);\n        scene.fog.color.set(0x1e1026);\n        ambientLight.color.set(0xff7700);\n        ambientLight.intensity = 0.9;\n        dirLight.color.set(0xffaa44);\n        dirLight.intensity = 1.2;\n        document.getElementById(\'env-icon\').innerText = \'🌅\';\n      } else {\n        scene.background.set(0x87ceeb);\n        scene.fog.color.set(0x87ceeb);\n        ambientLight.color.set(0xffffff);\n        ambientLight.intensity = 1.1;\n        dirLight.color.set(0xfff5e6);\n        dirLight.intensity = 1.4;\n        document.getElementById(\'env-icon\').innerText = \'☀️\';\n      }\n    }\n    setEnvironment(\'night\');\n\n    function toggleEnvironment() {\n      if (currentEnv === \'night\') setEnvironment(\'sunset\');\n      else if (currentEnv === \'sunset\') setEnvironment(\'day\');\n      else setEnvironment(\'night\');\n    }\n\n    /* =========================================================================\n       3. ROAD & ENVIRONMENT GEOMETRY\n       ========================================================================= */\n    const worldGroup = new THREE.Group();\n    scene.add(worldGroup);\n\n    // Ground plane\n    const groundGeo = new THREE.PlaneGeometry(160, 160);\n    const groundMat = new THREE.MeshStandardMaterial({\n      color: 0x0c121e,\n      roughness: 0.9,\n      metalness: 0.1\n    });\n    const groundMesh = new THREE.Mesh(groundGeo, groundMat);\n    groundMesh.rotation.x = -Math.PI / 2;\n    groundMesh.position.set(20, -0.05, 0);\n    groundMesh.receiveShadow = true;\n    worldGroup.add(groundMesh);\n\n    // Main Road (X: -10m to 50m, Z: -6m to +6m)\n    const roadLength = 60;\n    const roadWidth = ROAD_HALF * 2;\n    const roadGeo = new THREE.PlaneGeometry(roadLength, roadWidth);\n    const roadMat = new THREE.MeshStandardMaterial({\n      color: 0x181c24,\n      roughness: 0.8,\n      metalness: 0.2\n    });\n    const roadMesh = new THREE.Mesh(roadGeo, roadMat);\n    roadMesh.rotation.x = -Math.PI / 2;\n    roadMesh.position.set(20, 0, 0);\n    roadMesh.receiveShadow = true;\n    worldGroup.add(roadMesh);\n\n    // Road markings\n    function createRoadLine(x, z, len, w, color, isDashed = false) {\n      if (!isDashed) {\n        const geo = new THREE.PlaneGeometry(len, w);\n        const mat = new THREE.MeshBasicMaterial({ color: color });\n        const mesh = new THREE.Mesh(geo, mat);\n        mesh.rotation.x = -Math.PI / 2;\n        mesh.position.set(x, 0.01, z);\n        return mesh;\n      }\n      const group = new THREE.Group();\n      const dashLen = 2.0;\n      const gapLen = 2.0;\n      const count = Math.floor(len / (dashLen + gapLen));\n      const startX = x - len / 2;\n      for (let i = 0; i < count; i++) {\n        const dgeo = new THREE.PlaneGeometry(dashLen, w);\n        const dmat = new THREE.MeshBasicMaterial({ color: color });\n        const dmesh = new THREE.Mesh(dgeo, dmat);\n        dmesh.rotation.x = -Math.PI / 2;\n        dmesh.position.set(startX + i * (dashLen + gapLen) + dashLen / 2, 0.01, z);\n        group.add(dmesh);\n      }\n      return group;\n    }\n\n    // Outer solid white lines\n    worldGroup.add(createRoadLine(20, -5.8, 60, 0.2, 0xffffff));\n    worldGroup.add(createRoadLine(20, 5.8, 60, 0.2, 0xffffff));\n\n    // Center dashed yellow line\n    worldGroup.add(createRoadLine(20, 0, 60, 0.18, 0xfacc15, true));\n\n    // Lane divider dashed lines\n    worldGroup.add(createRoadLine(20, -3.0, 60, 0.12, 0xaaaaaa, true));\n    worldGroup.add(createRoadLine(20, 3.0, 60, 0.12, 0xaaaaaa, true));\n\n    // Start Line (x = 0)\n    worldGroup.add(createRoadLine(0, 0, 0.4, roadWidth, 0x00f0ff));\n\n    // Finish Arch / Line (x = 40m)\n    worldGroup.add(createRoadLine(40, 0, 0.6, roadWidth, 0x00ff9d));\n\n    // Curbs on edges\n    function createCurb(z) {\n      const curbGeo = new THREE.BoxGeometry(60, 0.25, 0.4);\n      const curbMat = new THREE.MeshStandardMaterial({ color: 0x334155, roughness: 0.6 });\n      const curb = new THREE.Mesh(curbGeo, curbMat);\n      curb.position.set(20, 0.1, z);\n      return curb;\n    }\n    worldGroup.add(createCurb(-6.2));\n    worldGroup.add(createCurb(6.2));\n\n    // Streetlights along road\n    const streetLightPositions = [-6, 6, 18, 30, 42];\n    streetLightPositions.forEach(x => {\n      [-7.2, 7.2].forEach(z => {\n        const pole = new THREE.Group();\n        pole.position.set(x, 0, z);\n\n        const mastGeo = new THREE.CylinderGeometry(0.1, 0.15, 6, 8);\n        const mastMat = new THREE.MeshStandardMaterial({ color: 0x475569, metalness: 0.8 });\n        const mast = new THREE.Mesh(mastGeo, mastMat);\n        mast.position.y = 3;\n        pole.add(mast);\n\n        const armGeo = new THREE.BoxGeometry(0.1, 0.1, 1.8);\n        const arm = new THREE.Mesh(armGeo, mastMat);\n        arm.position.set(0, 5.9, z > 0 ? -0.8 : 0.8);\n        pole.add(arm);\n\n        const bulbGeo = new THREE.SphereGeometry(0.2, 8, 8);\n        const bulbMat = new THREE.MeshBasicMaterial({ color: 0xfff0aa });\n        const bulb = new THREE.Mesh(bulbGeo, bulbMat);\n        bulb.position.set(0, 5.8, z > 0 ? -1.6 : 1.6);\n        pole.add(bulb);\n\n        const sl = new THREE.PointLight(0xffe899, 0.9, 14, 1.8);\n        sl.position.copy(bulb.position);\n        pole.add(sl);\n\n        worldGroup.add(pole);\n      });\n    });\n\n    // Distance markers\n    [10, 20, 30, 40].forEach(d => {\n      const gantry = new THREE.Group();\n      gantry.position.set(d, 0, 0);\n\n      const frameGeo = new THREE.BoxGeometry(0.2, 0.2, 13);\n      const frameMat = new THREE.MeshStandardMaterial({ color: 0x334155, metalness: 0.7 });\n      const bar = new THREE.Mesh(frameGeo, frameMat);\n      bar.position.y = 5.2;\n      gantry.add(bar);\n\n      const post1 = new THREE.Mesh(new THREE.CylinderGeometry(0.12, 0.12, 5.2), frameMat);\n      post1.position.set(0, 2.6, -6.4);\n      gantry.add(post1);\n\n      const post2 = post1.clone();\n      post2.position.set(0, 2.6, 6.4);\n      gantry.add(post2);\n\n      // Sign plate\n      const signGeo = new THREE.BoxGeometry(0.05, 0.8, 3.2);\n      const signMat = new THREE.MeshBasicMaterial({ color: d === 40 ? 0x00ff9d : 0x00f0ff });\n      const sign = new THREE.Mesh(signGeo, signMat);\n      sign.position.set(0, 4.8, 0);\n      gantry.add(sign);\n\n      worldGroup.add(gantry);\n    });\n\n    /* =========================================================================\n       4. EGO VEHICLE 3D MODEL & COCKPIT INTERIOR\n       ========================================================================= */\n    const carGroup = new THREE.Group();\n    scene.add(carGroup);\n\n    // Car Body Chassis\n    const bodyMat = new THREE.MeshStandardMaterial({\n      color: 0x1d4ed8,\n      roughness: 0.25,\n      metalness: 0.85\n    });\n    const carbonMat = new THREE.MeshStandardMaterial({\n      color: 0x111827,\n      roughness: 0.7,\n      metalness: 0.3\n    });\n    const glassMat = new THREE.MeshPhysicalMaterial({\n      color: 0x0284c7,\n      transparent: true,\n      opacity: 0.45,\n      roughness: 0.1,\n      metalness: 0.1,\n      transmission: 0.9,\n      ior: 1.5\n    });\n\n    // Lower chassis\n    const chassisGeo = new THREE.BoxGeometry(VEH_LEN, 0.65, HALF_W * 2);\n    const chassis = new THREE.Mesh(chassisGeo, bodyMat);\n    chassis.position.y = 0.5;\n    chassis.castShadow = true;\n    chassis.receiveShadow = true;\n    carGroup.add(chassis);\n\n    // Aerodynamic cabin / roof\n    const cabinGeo = new THREE.BoxGeometry(2.3, 0.65, HALF_W * 1.8);\n    const cabin = new THREE.Mesh(cabinGeo, glassMat);\n    cabin.position.set(-0.25, 1.05, 0);\n    cabin.castShadow = true;\n    carGroup.add(cabin);\n\n    // Roof cap\n    const roofGeo = new THREE.BoxGeometry(2.1, 0.08, HALF_W * 1.7);\n    const roof = new THREE.Mesh(roofGeo, bodyMat);\n    roof.position.set(-0.25, 1.4, 0);\n    carGroup.add(roof);\n\n    // Wheels (4 wheels)\n    const wheelGeo = new THREE.CylinderGeometry(0.36, 0.36, 0.28, 20);\n    const wheelMat = new THREE.MeshStandardMaterial({ color: 0x0f172a, roughness: 0.8 });\n    const rimMat = new THREE.MeshStandardMaterial({ color: 0xe2e8f0, metalness: 0.9, roughness: 0.2 });\n\n    function createWheel() {\n      const g = new THREE.Group();\n      const tire = new THREE.Mesh(wheelGeo, wheelMat);\n      tire.rotation.x = Math.PI / 2;\n      tire.castShadow = true;\n      g.add(tire);\n\n      const rimGeo = new THREE.CylinderGeometry(0.24, 0.24, 0.29, 12);\n      const rim = new THREE.Mesh(rimGeo, rimMat);\n      rim.rotation.x = Math.PI / 2;\n      g.add(rim);\n      return g;\n    }\n\n    const frontLeftWheelGroup = new THREE.Group();\n    frontLeftWheelGroup.position.set(1.3, 0.36, -HALF_W - 0.05);\n    const flWheel = createWheel();\n    frontLeftWheelGroup.add(flWheel);\n    carGroup.add(frontLeftWheelGroup);\n\n    const frontRightWheelGroup = new THREE.Group();\n    frontRightWheelGroup.position.set(1.3, 0.36, HALF_W + 0.05);\n    const frWheel = createWheel();\n    frontRightWheelGroup.add(frWheel);\n    carGroup.add(frontRightWheelGroup);\n\n    const rearLeftWheel = createWheel();\n    rearLeftWheel.position.set(-1.3, 0.36, -HALF_W - 0.05);\n    carGroup.add(rearLeftWheel);\n\n    const rearRightWheel = createWheel();\n    rearRightWheel.position.set(-1.3, 0.36, HALF_W + 0.05);\n    carGroup.add(rearRightWheel);\n\n    // Headlights (Twin SpotLights)\n    const headLightL = new THREE.SpotLight(0xffffff, 2.5, 30, Math.PI / 5, 0.3);\n    headLightL.position.set(2.1, 0.6, -0.6);\n    headLightL.target.position.set(12, 0, -0.6);\n    carGroup.add(headLightL);\n    carGroup.add(headLightL.target);\n\n    const headLightR = new THREE.SpotLight(0xffffff, 2.5, 30, Math.PI / 5, 0.3);\n    headLightR.position.set(2.1, 0.6, 0.6);\n    headLightR.target.position.set(12, 0, 0.6);\n    carGroup.add(headLightR);\n    carGroup.add(headLightR.target);\n\n    // Front glowing light bar\n    const fLightBarGeo = new THREE.BoxGeometry(0.05, 0.08, 1.4);\n    const fLightBarMat = new THREE.MeshBasicMaterial({ color: 0x00f0ff });\n    const fLightBar = new THREE.Mesh(fLightBarGeo, fLightBarMat);\n    fLightBar.position.set(2.11, 0.62, 0);\n    carGroup.add(fLightBar);\n\n    // Taillights\n    const tailLightBarGeo = new THREE.BoxGeometry(0.05, 0.08, 1.6);\n    const tailLightBarMat = new THREE.MeshBasicMaterial({ color: 0xff1144 });\n    const tailLightBar = new THREE.Mesh(tailLightBarGeo, tailLightBarMat);\n    tailLightBar.position.set(-2.11, 0.68, 0);\n    carGroup.add(tailLightBar);\n\n    // Underglow neon\n    const underglow = new THREE.PointLight(0x00f0ff, 1.2, 4);\n    underglow.position.set(0, 0.15, 0);\n    carGroup.add(underglow);\n\n    /* --- COCKPIT INTERIOR --- */\n    const cockpitGroup = new THREE.Group();\n    carGroup.add(cockpitGroup);\n\n    // Dashboard\n    const dashGeo = new THREE.BoxGeometry(0.7, 0.35, 1.55);\n    const dash = new THREE.Mesh(dashGeo, carbonMat);\n    dash.position.set(0.65, 0.8, 0);\n    cockpitGroup.add(dash);\n\n    // Steering Column & Wheel\n    const steerGroup = new THREE.Group();\n    steerGroup.position.set(0.42, 0.85, -0.38);\n    steerGroup.rotation.y = -Math.PI / 2;\n    steerGroup.rotation.x = -0.35; // tilt back toward driver\n\n    const wheelTorusGeo = new THREE.TorusGeometry(0.2, 0.024, 12, 28);\n    const wheelTorusMat = new THREE.MeshStandardMaterial({ color: 0x1f2937, roughness: 0.5 });\n    const wheelRim = new THREE.Mesh(wheelTorusGeo, wheelTorusMat);\n    steerGroup.add(wheelRim);\n\n    // Spokes\n    const spokeGeo = new THREE.BoxGeometry(0.38, 0.03, 0.015);\n    const spoke = new THREE.Mesh(spokeGeo, wheelTorusMat);\n    steerGroup.add(spoke);\n\n    const centerHubGeo = new THREE.CylinderGeometry(0.06, 0.06, 0.03, 16);\n    const centerHub = new THREE.Mesh(centerHubGeo, new THREE.MeshStandardMaterial({ color: 0x00f0ff, metalness: 0.9 }));\n    centerHub.rotation.x = Math.PI / 2;\n    steerGroup.add(centerHub);\n\n    cockpitGroup.add(steerGroup);\n\n    // Digital Driver Display (Instrument Cluster)\n    const clusterGeo = new THREE.PlaneGeometry(0.28, 0.12);\n    const clusterMat = new THREE.MeshBasicMaterial({ color: 0x00f0ff });\n    const cluster = new THREE.Mesh(clusterGeo, clusterMat);\n    cluster.position.set(0.58, 0.94, -0.38);\n    cluster.rotation.y = -Math.PI / 2;\n    cluster.rotation.x = -0.2;\n    cockpitGroup.add(cluster);\n\n    // Center Infotainment Tablet\n    const tabletGeo = new THREE.BoxGeometry(0.02, 0.26, 0.38);\n    const tabletMat = new THREE.MeshStandardMaterial({ color: 0x0f172a, roughness: 0.2 });\n    const tablet = new THREE.Mesh(tabletGeo, tabletMat);\n    tablet.position.set(0.48, 0.88, 0.08);\n    tablet.rotation.y = -0.3; // angled toward driver\n    cockpitGroup.add(tablet);\n\n    // Driver perspective camera target inside car\n    const driverSeatPos = new THREE.Vector3(-0.05, 1.1, -0.38);\n\n    /* =========================================================================\n       5. OBSTACLES & 3D RENDERING\n       ========================================================================= */\n    let obstacles = [];\n    const obstacleMeshes = [];\n\n    function makeObstacleData(kind, motion, x, y) {\n      const prop = OBJ_PROPS[kind];\n      let vx = 0.0, vy = 0.0;\n      if (kind !== "🕳️ Pothole") {\n        if (motion === "Crossing the road") {\n          vy = y >= 0 ? -prop.spd : prop.spd;\n        } else if (motion === "Moving ahead") {\n          vx = prop.spd;\n        }\n      }\n      return {\n        type: kind,\n        motion: motion,\n        x: x, y: y,\n        x0: x, y0: y,\n        vx: vx, vy: vy,\n        vy0: vy,\n        L: prop.L, W: prop.W,\n        animTime: Math.random() * 10\n      };\n    }\n\n    function createObstacle3D(o) {\n      const group = new THREE.Group();\n      group.userData = { type: o.type };\n      group.position.set(o.x, 0, o.y);\n\n      const prop = OBJ_PROPS[o.type];\n\n      if (o.type === "🧍 Pedestrian") {\n        // Humanoid Model\n        const skinMat = new THREE.MeshStandardMaterial({ color: 0xfbcfe8 });\n        const clothMat = new THREE.MeshStandardMaterial({ color: 0x0284c7, roughness: 0.6 });\n        const pantsMat = new THREE.MeshStandardMaterial({ color: 0x1e293b, roughness: 0.8 });\n\n        // Head\n        const head = new THREE.Mesh(new THREE.SphereGeometry(0.18, 12, 12), skinMat);\n        head.position.y = 1.55;\n        group.add(head);\n\n        // Torso\n        const torso = new THREE.Mesh(new THREE.CylinderGeometry(0.2, 0.22, 0.65, 8), clothMat);\n        torso.position.y = 1.05;\n        group.add(torso);\n\n        // Legs (animated in loop)\n        const legGeo = new THREE.CylinderGeometry(0.08, 0.07, 0.65, 8);\n        const legL = new THREE.Mesh(legGeo, pantsMat);\n        legL.position.set(0, 0.35, -0.12);\n        group.add(legL);\n\n        const legR = new THREE.Mesh(legGeo, pantsMat);\n        legR.position.set(0, 0.35, 0.12);\n        group.add(legR);\n\n        group.userData.legL = legL; group.userData.legR = legR; group.userData.type = "pedestrian";\n\n      } else if (o.type === "🐄 Cow") {\n        // Cow model (white with black patches)\n        const cowMat = new THREE.MeshStandardMaterial({ color: 0xf1f5f9, roughness: 0.7 });\n        const spotMat = new THREE.MeshStandardMaterial({ color: 0x0f172a, roughness: 0.7 });\n\n        // Body\n        const body = new THREE.Mesh(new THREE.BoxGeometry(1.6, 0.8, 0.7), cowMat);\n        body.position.y = 0.85;\n        group.add(body);\n\n        // Black spot on side\n        const spot = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.5, 0.72), spotMat);\n        spot.position.set(0.1, 0.88, 0);\n        group.add(spot);\n\n        // Head\n        const head = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.45, 0.4), cowMat);\n        head.position.set(0.9, 1.1, 0);\n        group.add(head);\n\n        // Horns\n        const hornMat = new THREE.MeshStandardMaterial({ color: 0xd97706 });\n        const hornL = new THREE.Mesh(new THREE.ConeGeometry(0.04, 0.2, 6), hornMat);\n        hornL.position.set(0.85, 1.35, -0.15);\n        hornL.rotation.z = -0.3;\n        group.add(hornL);\n\n        const hornR = hornL.clone();\n        hornR.position.set(0.85, 1.35, 0.15);\n        group.add(hornR);\n\n        // 4 Legs\n        const legGeo = new THREE.CylinderGeometry(0.08, 0.08, 0.55, 8);\n        const legFL = new THREE.Mesh(legGeo, cowMat); legFL.position.set(0.55, 0.28, -0.25); group.add(legFL);\n        const legFR = new THREE.Mesh(legGeo, cowMat); legFR.position.set(0.55, 0.28, 0.25); group.add(legFR);\n        const legBL = new THREE.Mesh(legGeo, cowMat); legBL.position.set(-0.55, 0.28, -0.25); group.add(legBL);\n        const legBR = new THREE.Mesh(legGeo, cowMat); legBR.position.set(-0.55, 0.28, 0.25); group.add(legBR);\n\n        group.userData.legFL = legFL; group.userData.legFR = legFR; group.userData.legBL = legBL; group.userData.legBR = legBR; group.userData.type = "cow";\n\n      } else if (o.type === "🛒 Pushcart") {\n        // Vendor Pushcart\n        const woodMat = new THREE.MeshStandardMaterial({ color: 0x92400e, roughness: 0.8 });\n        const metalMat = new THREE.MeshStandardMaterial({ color: 0x64748b, metalness: 0.8 });\n\n        // Crate\n        const crate = new THREE.Mesh(new THREE.BoxGeometry(1.4, 0.5, 0.9), woodMat);\n        crate.position.y = 0.65;\n        group.add(crate);\n\n        // Wheels\n        const wGeo = new THREE.CylinderGeometry(0.3, 0.3, 0.1, 16);\n        const wL = new THREE.Mesh(wGeo, metalMat);\n        wL.rotation.x = Math.PI / 2;\n        wL.position.set(0, 0.3, -0.52);\n        group.add(wL);\n\n        const wR = wL.clone();\n        wR.position.set(0, 0.3, 0.52);\n        group.add(wR);\n\n        // Handlebars\n        const handle = new THREE.Mesh(new THREE.BoxGeometry(0.6, 0.06, 0.8), metalMat);\n        handle.position.set(-0.9, 0.85, 0);\n        group.add(handle);\n\n      } else if (o.type === "🚗 Vehicle") {\n        // Sedan Obstacle\n        const carMat = new THREE.MeshStandardMaterial({ color: 0xe11d48, metalness: 0.8, roughness: 0.3 });\n        const body = new THREE.Mesh(new THREE.BoxGeometry(3.8, 0.7, 1.7), carMat);\n        body.position.y = 0.55;\n        group.add(body);\n\n        const cab = new THREE.Mesh(new THREE.BoxGeometry(2.1, 0.6, 1.5), glassMat);\n        cab.position.set(-0.2, 1.05, 0);\n        group.add(cab);\n\n        // Headlights\n        const fLight = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.1, 1.4), new THREE.MeshBasicMaterial({ color: 0xfef08a }));\n        fLight.position.set(1.91, 0.58, 0);\n        group.add(fLight);\n\n      } else { // 🕳️ Pothole\n        const pitGeo = new THREE.CylinderGeometry(0.6, 0.6, 0.08, 18);\n        const pitMat = new THREE.MeshStandardMaterial({ color: 0x05070c, roughness: 1.0 });\n        const pit = new THREE.Mesh(pitGeo, pitMat);\n        pit.position.y = 0.01;\n        group.add(pit);\n\n        // Hazard ring\n        const ringGeo = new THREE.RingGeometry(0.58, 0.75, 24);\n        const ringMat = new THREE.MeshBasicMaterial({ color: 0xf59e0b, side: THREE.DoubleSide });\n        const ring = new THREE.Mesh(ringGeo, ringMat);\n        ring.rotation.x = -Math.PI / 2;\n        ring.position.y = 0.02;\n        group.add(ring);\n      }\n\n      // Movement arrow indicator on ground\n      if (Math.abs(o.vx) + Math.abs(o.vy) > 0.01) {\n        const arrowDir = new THREE.Vector3(o.vx, 0, o.vy).normalize();\n        const arrow = new THREE.ArrowHelper(arrowDir, new THREE.Vector3(0, 0.04, 0), 2.0, 0xfacc15, 0.6, 0.4);\n        group.add(arrow);\n        group.userData.arrow = arrow;\n      }\n\n      scene.add(group);\n      return group;\n    }\n\n    function syncObstacleMeshes() {\n      // Clean up old\n      obstacleMeshes.forEach(m => scene.remove(m));\n      obstacleMeshes.length = 0;\n\n      // Add new\n      obstacles.forEach(o => {\n        const mesh = createObstacle3D(o);\n        obstacleMeshes.push(mesh);\n      });\n\n      document.getElementById(\'obs-count-badge\').innerText = `${obstacles.length} PLACED`;\n    }\n\n    /* =========================================================================\n       6. TIME-AWARE A* PATH PLANNING ALGORITHMS\n       ========================================================================= */\n    function fold(y, lim = LIM) {\n      const p = 4 * lim;\n      let m = ((y + lim) % p + p) % p;\n      return -lim + (m <= 2 * lim ? m : p - m);\n    }\n\n    function predict(o, t) {\n      const x = Math.min(o.x + o.vx * t, X_END + 8);\n      const y = o.vy !== 0 ? fold(o.y + o.vy * t) : o.y;\n      return { x, y };\n    }\n\n    function overlap(px, py, o, hx = HX0, hy = HY0, eps = 0.05) {\n      return Math.abs(px - o.x) < o.L / 2 + hx + eps && Math.abs(py - o.y) < o.W / 2 + hy + eps;\n    }\n\n    function densify(pts, step = RES) {\n      if (!pts || pts.length === 0) return [];\n      const out = [pts[0]];\n      for (let i = 0; i < pts.length - 1; i++) {\n        const a = pts[i];\n        const b = pts[i + 1];\n        const dist = Math.hypot(b[0] - a[0], b[1] - a[1]);\n        const n = Math.max(Math.ceil(dist / step), 1);\n        for (let k = 1; k <= n; k++) {\n          const t = k / n;\n          out.push([a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t]);\n        }\n      }\n      return out;\n    }\n\n    function analysePath(pts, obs) {\n      const dense = densify([[0.0, 0.0], ...pts]);\n      let blocked = false;\n      let firstBlockX = null;\n      for (let i = 0; i < dense.length; i++) {\n        const p = dense[i];\n        const t = (i * RES) / V_NOM;\n        if (Math.abs(p[1]) + HALF_W + 0.3 > ROAD_HALF) {\n          blocked = true;\n          if (firstBlockX === null) firstBlockX = p[0];\n          break;\n        }\n        for (const o of obs) {\n          const pred = predict(o, t);\n          if (Math.abs(p[0] - pred.x) < o.L / 2 + HX && Math.abs(p[1] - pred.y) < o.W / 2 + HY) {\n            blocked = true;\n            if (firstBlockX === null) firstBlockX = p[0];\n            break;\n          }\n        }\n        if (blocked) break;\n      }\n      return { blocked, firstBlockX };\n    }\n\n    function makePaths(n) {\n      const ys = n === 1 ? [0.0] : [];\n      if (n > 1) {\n        for (let i = 0; i < n; i++) {\n          ys.push(3.8 - (7.6 / (n - 1)) * i);\n        }\n      }\n      const dict = {};\n      ys.forEach((y, i) => {\n        dict[`Path ${i + 1}`] = [[8.0, y], [X_END, y]];\n      });\n      return dict;\n    }\n\n    // Min-heap for fast A*\n    class MinHeap {\n      constructor() { this.heap = []; }\n      push(item) {\n        this.heap.push(item);\n        this._up(this.heap.length - 1);\n      }\n      pop() {\n        if (!this.heap.length) return null;\n        const top = this.heap[0];\n        const b = this.heap.pop();\n        if (this.heap.length > 0) {\n          this.heap[0] = b;\n          this._down(0);\n        }\n        return top;\n      }\n      _up(i) {\n        while (i > 0) {\n          const p = (i - 1) >> 1;\n          if (this.heap[i].f < this.heap[p].f) {\n            [this.heap[i], this.heap[p]] = [this.heap[p], this.heap[i]];\n            i = p;\n          } else break;\n        }\n      }\n      _down(i) {\n        const len = this.heap.length;\n        while ((i << 1) + 1 < len) {\n          let left = (i << 1) + 1, right = left + 1, best = left;\n          if (right < len && this.heap[right].f < this.heap[left].f) best = right;\n          if (this.heap[best].f < this.heap[i].f) {\n            [this.heap[i], this.heap[best]] = [this.heap[best], this.heap[i]];\n            i = best;\n          } else break;\n        }\n      }\n      size() { return this.heap.length; }\n    }\n\n    function planRoute(goal, obs, start, v, nominalPath) {\n      const sx = start[0], sy = start[1];\n      const si = Math.round(sx / RES);\n      let sj = 0, minDiff = 999;\n      for (let j = 0; j < YS.length; j++) {\n        const diff = Math.abs(YS[j] - sy);\n        if (diff < minDiff) { minDiff = diff; sj = j; }\n      }\n      if (si >= XS.length - 1) {\n        return densify([start, [X_END, sy]]);\n      }\n\n      // Precalculate deviation penalty field from nominal path\n      const dev = new Float32Array(XS.length * YS.length);\n      const nomDense = densify([[0.0, 0.0], ...nominalPath]);\n      for (let i = 0; i < XS.length; i++) {\n        const x = XS[i];\n        for (let j = 0; j < YS.length; j++) {\n          const y = YS[j];\n          let minDist = 999;\n          for (let k = 0; k < nomDense.length; k += 4) {\n            const d = Math.hypot(x - nomDense[k][0], y - nomDense[k][1]);\n            if (d < minDist) minDist = d;\n          }\n          dev[i * YS.length + j] = minDist;\n        }\n      }\n\n      // Precompute collision mask with time-parameterized obstacle prediction\n      const blocked = new Uint8Array(XS.length * YS.length);\n      const vel = Math.max(v, 0.3);\n\n      for (let i = 0; i < XS.length; i++) {\n        const x = XS[i];\n        const t = (Math.max(x - sx, 0) / vel) * 1.1;\n        for (let j = 0; j < YS.length; j++) {\n          const y = YS[j];\n          const idx = i * YS.length + j;\n          if (Math.abs(y) + HALF_W + 0.3 > ROAD_HALF) {\n            blocked[idx] = 1;\n            continue;\n          }\n          for (const o of obs) {\n            const pred = predict(o, t);\n            const unc = Math.min(0.2 + 0.15 * t * (Math.abs(o.vx) + Math.abs(o.vy)), 1.2);\n            if (Math.abs(x - pred.x) < o.L / 2 + HX + unc && Math.abs(y - pred.y) < o.W / 2 + HY + unc) {\n              blocked[idx] = 1;\n              break;\n            }\n          }\n        }\n      }\n\n      // Unblock immediate vehicle spot\n      for (let i = Math.max(si - 2, 0); i <= Math.min(si + 5, XS.length - 1); i++) {\n        for (let j = Math.max(sj - 4, 0); j <= Math.min(sj + 4, YS.length - 1); j++) {\n          blocked[i * YS.length + j] = 0;\n        }\n      }\n\n      // Find free goal cell closest to desired target\n      let gi = -1, gj = -1, bestDist = 999999;\n      for (let i = XS.length - 1; i >= XS.length - 5 && gi === -1; i--) {\n        for (let j = 0; j < YS.length; j++) {\n          if (!blocked[i * YS.length + j]) {\n            const d = Math.hypot(XS[i] - goal[0], YS[j] - goal[1]);\n            if (d < bestDist) { bestDist = d; gi = i; gj = j; }\n          }\n        }\n      }\n      if (gi === -1) return null;\n\n      const gScore = new Float64Array(XS.length * YS.length).fill(Infinity);\n      const parent = new Int32Array(XS.length * YS.length).fill(-1);\n      const startIdx = si * YS.length + sj;\n      gScore[startIdx] = 0.0;\n\n      const heap = new MinHeap();\n      heap.push({ f: RES * (gi - si), g: 0.0, i: si, j: sj });\n\n      let done = false;\n      let endI = -1, endJ = -1;\n\n      while (heap.size() > 0) {\n        const cur = heap.pop();\n        const curIdx = cur.i * YS.length + cur.j;\n        if (cur.g > gScore[curIdx] + 1e-5) continue;\n        if (cur.i === gi && Math.abs(cur.j - gj) <= 1) {\n          done = true; endI = cur.i; endJ = cur.j;\n          break;\n        }\n        for (let dj = -1; dj <= 1; dj++) {\n          const ni = cur.i + 1;\n          const nj = cur.j + dj;\n          if (ni >= XS.length || nj < 0 || nj >= YS.length) continue;\n          const nIdx = ni * YS.length + nj;\n          if (blocked[nIdx]) continue;\n\n          const devCost = dev[nIdx];\n          const stepCost = Math.hypot(1, dj) * RES * (1 + 0.8 * devCost) + 0.02 * Math.abs(dj);\n          const ng = cur.g + stepCost;\n\n          if (ng < gScore[nIdx]) {\n            gScore[nIdx] = ng;\n            parent[nIdx] = curIdx;\n            const h = RES * (gi - ni) + Math.abs(gj - nj) * RES * 0.5;\n            heap.push({ f: ng + h, g: ng, i: ni, j: nj });\n          }\n        }\n      }\n\n      if (!done) return null;\n\n      // Reconstruct\n      const raw = [];\n      let curr = endI * YS.length + endJ;\n      while (curr !== -1) {\n        const ci = Math.floor(curr / YS.length);\n        const cj = curr % YS.length;\n        raw.push([XS[ci], YS[cj]]);\n        if (ci === si && cj === sj) break;\n        curr = parent[curr];\n      }\n      raw.reverse();\n      raw[0] = [start[0], start[1]];\n\n      // 7-point moving average smoothing\n      const k = 7;\n      if (raw.length <= k) return densify(raw);\n\n      const smoothed = [];\n      for (let i = 0; i < raw.length; i++) {\n        let sx = 0, sy = 0, count = 0;\n        for (let w = -Math.floor(k / 2); w <= Math.floor(k / 2); w++) {\n          const idx = Math.min(Math.max(i + w, 0), raw.length - 1);\n          sx += raw[idx][0]; sy += raw[idx][1]; count++;\n        }\n        smoothed.push([sx / count, sy / count]);\n      }\n      smoothed[0] = raw[0];\n      smoothed[smoothed.length - 1] = raw[raw.length - 1];\n\n      return densify(smoothed);\n    }\n\n    \n    /* =========================================================================\n       MANUAL DRIVE MODE & KEYBOARD CONTROLS (WASD / ARROW KEYS)\n       ========================================================================= */\n    // driveMode defined below\n    const keys = {};\n\n    function pressKey(code, isDown) {\n      keys[code.toLowerCase()] = isDown;\n      keys[code] = isDown;\n      if (isDown) {\n        if (!sim.running) startDriving();\n      }\n    }\n\n    window.addEventListener(\'keydown\', (e) => {\n      keys[e.key.toLowerCase()] = true;\n      keys[e.code] = true;\n      const k = e.key.toLowerCase();\n      if ([\'w\', \'a\', \'s\', \'d\', \'arrowup\', \'arrowdown\', \'arrowleft\', \'arrowright\'].includes(k)) {\n        if (!sim.running) {\n          startDriving();\n        }\n      }\n    });\n\n    window.addEventListener(\'keyup\', (e) => {\n      keys[e.key.toLowerCase()] = false;\n      keys[e.code] = false;\n    });\n\n    function setDriveMode(mode) {\n      driveMode = mode;\n      document.getElementById(\'mode-btn-manual\').classList.toggle(\'active\', mode === \'manual\');\n      document.getElementById(\'mode-btn-auto\').classList.toggle(\'active\', mode === \'autopilot\');\n      const manualDock = document.getElementById(\'manual-controls-dock\');\n      if (manualDock) manualDock.classList.toggle(\'hidden\', mode !== \'manual\');\n\n      if (mode === \'manual\') {\n        toast("🎮 MANUAL MODE: Use [W][A][S][D] or Arrow Keys to steer & accelerate!");\n        updateStatusDisplay("MANUAL DRIVE // WASD READY", "#00ff9d");\n        hideBlockAlert();\n        if (!sim.running) startDriving();\n      } else {\n        toast("🤖 AUTOPILOT MODE: AI Path Planner active!");\n        updateStatusDisplay("AUTOPILOT READY", "#00f0ff");\n      }\n    }\n\n    function showBlockAlert() {\n      const banner = document.getElementById(\'block-alert-banner\');\n      if (banner) banner.classList.add(\'show\');\n    }\n\n    function hideBlockAlert() {\n      const banner = document.getElementById(\'block-alert-banner\');\n      if (banner) banner.classList.remove(\'show\');\n    }\n\n    function clearPathAhead() {\n      // Remove obstacles within 6m in front of vehicle\n      const countBefore = obstacles.length;\n      obstacles = obstacles.filter(o => o.x < sim.pos[0] - 1 || o.x > sim.pos[0] + 6.5);\n      syncObstacleMeshes();\n      hideBlockAlert();\n      toast(`Cleared ${countBefore - obstacles.length} obstacle(s) in front of vehicle!`);\n      if (sim.running) triggerReplan();\n    }\n\n    /* =========================================================================\n       7. SIMULATION STATE & CONTROLLER\n       ========================================================================= */\n    let pathCount = 3;\n    let paths = makePaths(pathCount);\n    let chosenPathName = "Path 1";\n    let selectedObstacleType = "🧍 Pedestrian";\n    let selectedObstacleMotion = "Static";\n    let simSpeedMultiplier = 1.0;\n\n    let sim = {\n      running: false,\n      pos: [0.0, 0.0],\n      heading: 0.0,\n      steerAngle: 0.0,\n      velocity: 0.0,\n      route: [],\n      idx: 0,\n      trail: [[0.0, 0.0]],\n      replans: 0,\n      status: "ready", // ready, driving, waiting, done, collided\n      tick: 0\n    };\n\n    // 3D Path Lines & Ribbons\n    const pathLineGroup = new THREE.Group();\n    scene.add(pathLineGroup);\n\n    let activeTrajectoryMesh = null;\n    let trailLineMesh = null;\n\n    function render3DPaths() {\n      // Remove previous path ribbons\n      while (pathLineGroup.children.length > 0) {\n        pathLineGroup.remove(pathLineGroup.children[0]);\n      }\n\n      Object.entries(paths).forEach(([name, pts]) => {\n        const fullPts = densify([[0.0, 0.0], ...pts]);\n        const status = analysePath(pts, obstacles);\n        const isSelected = name === chosenPathName;\n\n        const curve = new THREE.CatmullRomCurve3(\n          fullPts.map(p => new THREE.Vector3(p[0], 0.08, p[1]))\n        );\n        const tubeGeo = new THREE.TubeGeometry(curve, 64, isSelected ? 0.12 : 0.05, 8, false);\n        const tubeMat = new THREE.MeshBasicMaterial({\n          color: status.blocked ? 0xff3366 : (isSelected ? 0x00f0ff : 0x334155),\n          transparent: true,\n          opacity: isSelected ? 0.95 : 0.45\n        });\n        const tube = new THREE.Mesh(tubeGeo, tubeMat);\n        pathLineGroup.add(tube);\n      });\n    }\n\n    function renderActiveTrajectory() {\n      if (activeTrajectoryMesh) {\n        scene.remove(activeTrajectoryMesh);\n        activeTrajectoryMesh = null;\n      }\n      if (sim.route.length > sim.idx + 1 && sim.status === "driving") {\n        const remPts = sim.route.slice(sim.idx);\n        const curve = new THREE.CatmullRomCurve3(\n          remPts.map(p => new THREE.Vector3(p[0], 0.12, p[1]))\n        );\n        const tubeGeo = new THREE.TubeGeometry(curve, Math.min(remPts.length, 60), 0.15, 8, false);\n        const tubeMat = new THREE.MeshBasicMaterial({ color: 0x00ff9d, transparent: true, opacity: 0.9 });\n        activeTrajectoryMesh = new THREE.Mesh(tubeGeo, tubeMat);\n        scene.add(activeTrajectoryMesh);\n      }\n    }\n\n    function renderTireTrail() {\n      if (trailLineMesh) {\n        scene.remove(trailLineMesh);\n        trailLineMesh = null;\n      }\n      if (sim.trail.length > 2) {\n        const pts = sim.trail.map(p => new THREE.Vector3(p[0], 0.03, p[1]));\n        const geo = new THREE.BufferGeometry().setFromPoints(pts);\n        const mat = new THREE.LineBasicMaterial({ color: 0x00f0ff, transparent: true, opacity: 0.6, linewidth: 3 });\n        trailLineMesh = new THREE.Line(geo, mat);\n        scene.add(trailLineMesh);\n      }\n    }\n\n    function updatePathUI() {\n      const container = document.getElementById(\'paths-list\');\n      container.innerHTML = \'\';\n      Object.entries(paths).forEach(([name, pts]) => {\n        const status = analysePath(pts, obstacles);\n        const card = document.createElement(\'div\');\n        card.className = `path-card ${name === chosenPathName ? \'selected\' : \'\'}`;\n        card.onclick = () => selectPath(name);\n\n        card.innerHTML = `\n          <div class="path-info">\n            <span class="path-name">${name}</span>\n            <span class="path-meta">${status.blocked ? `Blocked at ${status.firstBlockX.toFixed(1)}m` : \'Clear corridor\'}</span>\n          </div>\n          <span class="${status.blocked ? \'badge-blocked\' : \'badge-clear\'}">\n            ${status.blocked ? \'⛔ BLOCKED\' : \'✅ CLEAR\'}\n          </span>\n        `;\n        container.appendChild(card);\n      });\n      render3DPaths();\n    }\n\n    function selectPath(name) {\n      chosenPathName = name;\n      updatePathUI();\n      if (sim.running) {\n        triggerReplan();\n      }\n    }\n\n    function updatePathCount(val) {\n      pathCount = parseInt(val);\n      document.getElementById(\'path-slider-val\').innerText = val;\n      document.getElementById(\'path-count-lbl\').innerText = `${val} PATHS`;\n      paths = makePaths(pathCount);\n      if (!paths[chosenPathName]) {\n        chosenPathName = Object.keys(paths)[0];\n      }\n      updatePathUI();\n      if (sim.running) triggerReplan();\n    }\n\n    function selectObstacle(type, el) {\n      selectedObstacleType = type;\n      document.querySelectorAll(\'.spawner-item\').forEach(i => i.classList.remove(\'active\'));\n      if (el) el.classList.add(\'active\');\n    }\n\n    function selectMotion(motion, el) {\n      selectedObstacleMotion = motion;\n      document.querySelectorAll(\'.motion-btn\').forEach(b => b.classList.remove(\'active\'));\n      if (el) el.classList.add(\'active\');\n    }\n\n    function setSpeed(mode, el) {\n      document.querySelectorAll(\'#spd-slow, #spd-norm, #spd-fast\').forEach(b => b.classList.remove(\'active\'));\n      if (el) el.classList.add(\'active\');\n      if (mode === \'Slow\') simSpeedMultiplier = 0.5;\n      else if (mode === \'Fast\') simSpeedMultiplier = 2.0;\n      else simSpeedMultiplier = 1.0;\n    }\n\n    function toast(text) {\n      const t = document.getElementById(\'toast-msg\');\n      t.innerText = text;\n      t.classList.add(\'show\');\n      setTimeout(() => t.classList.remove(\'show\'), 2400);\n    }\n\n    /* =========================================================================\n       8. WEB AUDIO SOUND FX SYNTHESIZER (ZERO ASSETS REQUIRED)\n       ========================================================================= */\n    let audioCtx = null;\n    let audioEnabled = true;\n    let engineOsc = null;\n    let engineGain = null;\n\n    function initAudio() {\n      if (audioCtx) return;\n      try {\n        const AudioClass = window.AudioContext || window.webkitAudioContext;\n        audioCtx = new AudioClass();\n\n        // Electric motor engine hum\n        engineOsc = audioCtx.createOscillator();\n        engineGain = audioCtx.createGain();\n        engineOsc.type = \'sawtooth\';\n        engineOsc.frequency.setValueAtTime(45, audioCtx.currentTime);\n        engineGain.gain.setValueAtTime(0.01, audioCtx.currentTime);\n\n        const filter = audioCtx.createBiquadFilter();\n        filter.type = \'lowpass\';\n        filter.frequency.setValueAtTime(300, audioCtx.currentTime);\n\n        engineOsc.connect(filter);\n        filter.connect(engineGain);\n        engineGain.connect(audioCtx.destination);\n        engineOsc.start();\n      } catch (e) {\n        console.warn(\'Audio not supported:\', e);\n      }\n    }\n\n    function playChime(freq = 587, type = \'sine\', duration = 0.25, vol = 0.15) {\n      if (!audioEnabled || !audioCtx) return;\n      try {\n        const osc = audioCtx.createOscillator();\n        const gain = audioCtx.createGain();\n        osc.type = type;\n        osc.frequency.setValueAtTime(freq, audioCtx.currentTime);\n        gain.gain.setValueAtTime(vol, audioCtx.currentTime);\n        gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + duration);\n        osc.connect(gain);\n        gain.connect(audioCtx.destination);\n        osc.start();\n        osc.stop(audioCtx.currentTime + duration);\n      } catch (e) {}\n    }\n\n    function toggleAudio() {\n      audioEnabled = !audioEnabled;\n      document.getElementById(\'sound-icon\').innerText = audioEnabled ? \'🔊\' : \'🔇\';\n      if (!audioEnabled && engineGain) {\n        engineGain.gain.setValueAtTime(0, audioCtx.currentTime);\n      }\n    }\n\n    \n    function engageAutopilot() {\n      driveMode = \'autopilot\';\n      setDriveMode(\'autopilot\');\n      startDriving(\'autopilot\');\n    }\n\n    \n    /* =========================================================================\n       HIGH-PERFORMANCE 3D DRIVING ENGINE (Mirrors 2D View & Reaches Goal in 10s)\n       ========================================================================= */\n    let driveMode = \'auto\'; // \'auto\' (default, moves like 2D) or \'manual\'\n    let targetSpeed = 4.0;  // 4.0 m/s => 40m / 4.0m/s = exactly 10.0 seconds to goal\n\n    function startDriving3D() {\n      initAudio();\n      playChime(659, \'triangle\', 0.35, 0.2);\n\n      // If already finished or at the end, reset first\n      if (sim.status === \'done\' || sim.pos[0] >= X_END - 0.5) {\n        resetSimulation();\n      }\n\n      // If already driving, toggle pause\n      if (sim.running) {\n        pauseDriving3D();\n        return;\n      }\n\n      const nominal = paths[chosenPathName] || Object.values(paths)[0];\n      const nominalRoute = densify([[0.0, 0.0], ...nominal]);\n\n      // Plan initial A* route, or fallback to nominal route straight to goal\n      let planned = null;\n      try {\n        planned = planRoute(nominal[nominal.length - 1], obstacles, sim.pos[0] < 0.5 ? [0.0, 0.0] : sim.pos, targetSpeed, nominal);\n      } catch (e) {\n        console.warn(\'planRoute error, using nominal\', e);\n      }\n\n      sim.route = (planned && planned.length > 5) ? planned : nominalRoute;\n      sim.running = true;\n      sim.status = \'driving\';\n      sim.velocity = targetSpeed;\n      if (sim.pos[0] < 0.5) {\n        sim.idx = 0;\n        sim.distProgress = 0.0;\n        sim.pos = [0.0, 0.0];\n        sim.heading = 0.0;\n        sim.trail = [[0.0, 0.0]];\n        sim.replans = 0;\n      }\n\n      // Update UI button states\n      const b1 = document.getElementById(\'btn-drive\');\n      if (b1) { b1.innerText = "⏸ Pause driving"; b1.classList.add(\'stopped\'); }\n      const topBtn = document.getElementById(\'btn-top-drive\');\n      if (topBtn) { topBtn.innerText = "⏸ Pause driving"; topBtn.classList.add(\'stopped\'); }\n      const centerCard = document.getElementById(\'center-ignition-card\');\n      if (centerCard) centerCard.classList.add(\'hidden\');\n\n      updateStatusDisplay(`Driving ${chosenPathName}. Dynamic obstacle avoidance active.`, "#00ff9d");\n      toast(`▶ Started driving along ${chosenPathName} (Goal in ~10s)!`);\n      renderActiveTrajectory();\n    }\n\n    function pauseDriving3D() {\n      sim.running = false;\n      const b1 = document.getElementById(\'btn-drive\');\n      if (b1) { b1.innerText = "▶ Start driving"; b1.classList.remove(\'stopped\'); }\n      const topBtn = document.getElementById(\'btn-top-drive\');\n      if (topBtn) { topBtn.innerText = "▶ Start driving"; topBtn.classList.remove(\'stopped\'); }\n      const centerCard = document.getElementById(\'center-ignition-card\');\n      if (centerCard) {\n        centerCard.classList.remove(\'hidden\');\n        centerCard.querySelector(\'.ignition-title\').innerText = "▶ Start driving";\n      }\n      updateStatusDisplay("PAUSED // Click \'Start driving\' to resume", "#ffaa00");\n    }\n\n    // Keep backwards-compatibility aliases\n    function toggleDrive() { startDriving3D(); }\n    function engageAutopilot() { startDriving3D(); }\n    function startDriving() { startDriving3D(); }\n\n    function resetSimulation() {\n      sim.running = false;\n      sim.status = "ready";\n      sim.pos = [0.0, 0.0];\n      sim.heading = 0.0;\n      sim.steerAngle = 0.0;\n      sim.velocity = 0.0;\n      sim.idx = 0;\n      sim.distProgress = 0.0;\n      sim.trail = [[0.0, 0.0]];\n      sim.replans = 0;\n      carGroup.position.set(0, 0, 0);\n      carGroup.rotation.y = 0;\n      steerGroup.rotation.z = 0;\n\n      // Reset obstacles to initial spots\n      obstacles.forEach(o => {\n        o.x = o.x0; o.y = o.y0; o.vy = o.vy0;\n      });\n      syncObstacleMeshes();\n\n      const b1 = document.getElementById(\'btn-drive\');\n      if (b1) { b1.innerText = "▶ Start driving"; b1.classList.remove(\'stopped\'); }\n      const topBtn = document.getElementById(\'btn-top-drive\');\n      if (topBtn) { topBtn.innerText = "▶ Start driving"; topBtn.classList.remove(\'stopped\'); }\n      const centerCard = document.getElementById(\'center-ignition-card\');\n      if (centerCard) {\n        centerCard.classList.remove(\'hidden\');\n        centerCard.querySelector(\'.ignition-title\').innerText = "▶ Start driving";\n      }\n      updateStatusDisplay("READY // Click \'Start driving\'", "#00f0ff");\n      renderActiveTrajectory();\n      renderTireTrail();\n      updatePathUI();\n      updateTelemetryUI();\n    }\n\n    function setSpeed(mode, el) {\n      document.querySelectorAll(\'#spd-slow, #spd-norm, #spd-fast\').forEach(b => b.classList.remove(\'active\'));\n      if (el) el.classList.add(\'active\');\n      if (mode === \'Slow\') {\n        targetSpeed = 2.5; // ~16s\n        simSpeedMultiplier = 0.625;\n      } else if (mode === \'Fast\') {\n        targetSpeed = 6.5; // ~6s\n        simSpeedMultiplier = 1.625;\n      } else {\n        targetSpeed = 4.0; // exactly 10s\n        simSpeedMultiplier = 1.0;\n      }\n      if (sim.running) sim.velocity = targetSpeed;\n    }\n\n    \n    \n    /* =========================================================================\n       ZERO-COLLISION AUTONOMOUS DRIVING & PREDICTIVE OBSTACLE AVOIDANCE\n       ========================================================================= */\n    let lastTime = performance.now();\n    let currentTargetY = 0.0;\n\n    function willCollide(x, y, obs, extraBuffer = 0.35) {\n      for (let i = 0; i < obs.length; i++) {\n        const o = obs[i];\n        const bx = o.L / 2 + HX0 + extraBuffer;\n        const by = o.W / 2 + HY0 + extraBuffer;\n        if (Math.abs(x - o.x) < bx && Math.abs(y - o.y) < by) {\n          return o;\n        }\n      }\n      return null;\n    }\n\n    function stepWorld() {\n      const now = performance.now();\n      const dt = Math.min((now - lastTime) / 1000, 0.05); // seconds\n      lastTime = now;\n\n      if (!sim.running) return;\n\n      sim.tick++;\n      const currentDT = dt;\n\n      // 1. Move Obstacles & Animate\n      obstacles.forEach((o, i) => {\n        let nx = Math.min(o.x + o.vx * currentDT, X_END + 8);\n        let ny = o.y + o.vy * currentDT;\n        let nvy = o.vy;\n\n        if (Math.abs(ny) > LIM) {\n          ny = Math.sign(ny) * (2 * LIM - Math.abs(ny));\n          nvy = -o.vy;\n        }\n\n        // Check if car is directly adjacent\n        const bx = o.L / 2 + HX0 + 0.15;\n        const by = o.W / 2 + HY0 + 0.15;\n        if (Math.abs(sim.pos[0] - o.x) < bx && Math.abs(sim.pos[1] - o.y) < by) {\n          // Obstacle yields\n        } else {\n          o.x = nx;\n          o.y = ny;\n          o.vy = nvy;\n        }\n\n        // Animate 3D Obstacle Mesh\n        const mesh = obstacleMeshes[i];\n        if (mesh) {\n          mesh.position.set(o.x, 0, o.y);\n          o.animTime = (o.animTime || 0) + currentDT * 4.0;\n          if (mesh.userData.type === "pedestrian") {\n            const swing = Math.sin(o.animTime) * 0.4;\n            if (mesh.userData.legL) mesh.userData.legL.rotation.z = swing;\n            if (mesh.userData.legR) mesh.userData.legR.rotation.z = -swing;\n          } else if (mesh.userData.type === "cow") {\n            const walk = Math.sin(o.animTime) * 0.3;\n            if (mesh.userData.legFL) mesh.userData.legFL.rotation.z = walk;\n            if (mesh.userData.legFR) mesh.userData.legFR.rotation.z = -walk;\n            if (mesh.userData.legBL) mesh.userData.legBL.rotation.z = -walk;\n            if (mesh.userData.legBR) mesh.userData.legBR.rotation.z = walk;\n          }\n        }\n      });\n\n      // 2. Zero-Collision Driving Controller\n      if (sim.status === "driving") {\n        const speed = targetSpeed || 4.0;\n\n        // --- PREDICTIVE SCAN AHEAD 18 METERS ---\n        const threats = [];\n        for (let i = 0; i < obstacles.length; i++) {\n          const o = obstacles[i];\n          const dx = o.x - sim.pos[0];\n          if (dx > -0.5 && dx < 18.0) {\n            // Predict where obstacle will be when car gets there\n            const t = Math.max(dx, 0) / Math.max(speed, 1.0);\n            const predY = (o.vy !== 0) ? fold(o.y + o.vy * t) : o.y;\n            if (Math.abs(predY - sim.pos[1]) < o.W / 2 + HY0 + 1.2) {\n              threats.push({ dx, o, predY });\n            }\n          }\n        }\n        threats.sort((a, b) => a.dx - b.dx);\n\n        // --- OPTIMAL COLLISION-FREE LANE SELECTION ---\n        if (threats.length > 0) {\n          // Find the best clear lateral corridor among 9 candidates across the road\n          const candidateLanes = [-4.5, -3.5, -2.2, -1.0, 0.0, 1.0, 2.2, 3.5, 4.5];\n          let bestLane = currentTargetY;\n          let bestSafetyScore = -999999;\n\n          candidateLanes.forEach(lane => {\n            let minObstacleDistance = 999;\n            for (let t = 0; t < threats.length; t++) {\n              const th = threats[t];\n              const lateralDist = Math.abs(lane - th.predY) - (th.o.W / 2 + HY0);\n              if (lateralDist < minObstacleDistance) {\n                minObstacleDistance = lateralDist;\n              }\n            }\n\n            // Score = high clearance bonus - deviation penalty from current lane\n            const deviationPenalty = Math.abs(lane - currentTargetY) * 0.4;\n            const score = minObstacleDistance - deviationPenalty;\n\n            if (score > bestSafetyScore) {\n              bestSafetyScore = score;\n              bestLane = lane;\n            }\n          });\n\n          currentTargetY = bestLane;\n          updateStatusDisplay(`Steering around obstacle (${threats[0].o.type.split(\' \')[1]}). Clearance: OK`, "#00ff9d");\n        } else {\n          // No immediate threats ahead: gently align with chosen nominal path\n          const nominalY = paths[chosenPathName] ? paths[chosenPathName][0][1] : 0.0;\n          currentTargetY = currentTargetY * 0.95 + nominalY * 0.05;\n          updateStatusDisplay(`Driving ${chosenPathName}. Way is 100% CLEAR.`, "#00f0ff");\n        }\n\n        // --- SMOOTH LATERAL STEERING (Y) ---\n        const lateralDiff = currentTargetY - sim.pos[1];\n        const steerSpeed = 3.8 * currentDT; // lateral m/s\n        const dy = THREE.MathUtils.clamp(lateralDiff, -steerSpeed, steerSpeed);\n        const oldY = sim.pos[1];\n        sim.pos[1] += dy;\n\n        // Keep inside road curbs\n        sim.pos[1] = THREE.MathUtils.clamp(sim.pos[1], -ROAD_HALF + 0.9, ROAD_HALF - 0.9);\n\n        // --- HARD COLLISION SHIELD (X) ---\n        // Candidate forward position\n        const candX = sim.pos[0] + speed * currentDT;\n        const collisionThreat = willCollide(candX, sim.pos[1], obstacles, 0.35);\n\n        if (!collisionThreat) {\n          // Path forward is completely safe: ADVANCE!\n          const oldX = sim.pos[0];\n          sim.pos[0] = candX;\n          sim.velocity = speed;\n\n          // Calculate heading & steering wheel angle\n          const fdx = sim.pos[0] - oldX;\n          const fdy = sim.pos[1] - oldY;\n          if (Math.hypot(fdx, fdy) > 0.001) {\n            const heading = Math.atan2(fdy, fdx);\n            const steerDelta = heading - sim.heading;\n            sim.heading = heading;\n            sim.steerAngle = THREE.MathUtils.clamp(steerDelta * 22.0, -0.65, 0.65);\n          }\n\n          if (sim.tick % 4 === 0) {\n            sim.trail.push([sim.pos[0], sim.pos[1]]);\n          }\n        } else {\n          // Obstacle directly in front of bumper: EMERGENCY BRAKE & ESCAPE STEER!\n          sim.velocity = 0;\n          updateStatusDisplay(`🛑 BRAKING SAFELY: Obstacle ${collisionThreat.type.split(\' \')[1]} directly ahead. Re-routing...`, "#ffaa00");\n          triggerWarningStrobe();\n\n          // Force lateral escape towards clearer side\n          const escapeSign = sim.pos[1] >= collisionThreat.y ? 1.0 : -1.0;\n          sim.pos[1] = THREE.MathUtils.clamp(sim.pos[1] + escapeSign * 4.2 * currentDT, -ROAD_HALF + 0.9, ROAD_HALF - 0.9);\n        }\n\n        // --- FINISH LINE (40m) CHECK ---\n        if (sim.pos[0] >= X_END - 0.1) {\n          sim.running = false;\n          sim.status = "done";\n          sim.velocity = 0;\n          playChime(784, \'triangle\', 0.6, 0.3);\n          toast("🏁 Arrived safely at the goal with ZERO collisions!");\n          updateStatusDisplay(`🏁 Arrived at goal with ZERO collisions!`, "#00ff9d");\n\n          const b1 = document.getElementById(\'btn-drive\');\n          if (b1) { b1.innerText = "▶ Start driving"; b1.classList.remove(\'stopped\'); }\n          const topBtn = document.getElementById(\'btn-top-drive\');\n          if (topBtn) { topBtn.innerText = "▶ Start driving"; topBtn.classList.remove(\'stopped\'); }\n        }\n      }\n\n      // 3. Physical Collision Verification (Audit)\n      const auditOverlap = willCollide(sim.pos[0], sim.pos[1], obstacles, 0.0);\n      if (auditOverlap) {\n        sim.collided = true;\n        triggerWarningStrobe();\n        playChime(150, \'sawtooth\', 0.15, 0.3);\n      }\n\n      // 4. Update 3D Vehicle Transforms & Cockpit Animations\n      carGroup.position.set(sim.pos[0], 0, sim.pos[1]);\n      carGroup.rotation.y = -sim.heading;\n\n      // Front wheel steer\n      frontLeftWheelGroup.rotation.y = -sim.steerAngle;\n      frontRightWheelGroup.rotation.y = -sim.steerAngle;\n\n      // Cockpit 3D steering wheel turns dynamically with steer angle\n      steerGroup.rotation.z = -sim.steerAngle * 4.5;\n\n      // Wheels spin with forward velocity\n      const spin = (sim.velocity * currentDT) / 0.36;\n      flWheel.rotation.y += spin;\n      frWheel.rotation.y += spin;\n      rearLeftWheel.rotation.y += spin;\n      rearRightWheel.rotation.y += spin;\n\n      // Engine sound pitch\n      if (audioEnabled && engineOsc && engineGain) {\n        const pitch = 45 + sim.velocity * 25;\n        engineOsc.frequency.setValueAtTime(pitch, audioCtx.currentTime);\n        engineGain.gain.setValueAtTime(sim.velocity > 0 ? 0.05 : 0.015, audioCtx.currentTime);\n      }\n\n      // 5. Update Telemetry UI\n      updateTelemetryUI();\n      if (sim.tick % 8 === 0) renderTireTrail();\n    }\n\n    function updateStatusDisplay(text, color) {\n      document.getElementById(\'status-text\').innerText = text;\n      document.getElementById(\'status-text\').style.color = color;\n      document.getElementById(\'status-dot\').style.background = color;\n      document.getElementById(\'status-dot\').style.boxShadow = `0 0 10px ${color}`;\n    }\n\n    function triggerWarningStrobe() {\n      const w = document.getElementById(\'warning-strobe\');\n      w.style.opacity = \'1\';\n      setTimeout(() => w.style.opacity = \'0\', 250);\n    }\n\n    function updateTelemetryUI() {\n      document.getElementById(\'tel-speed\').innerText = sim.velocity.toFixed(1);\n      document.getElementById(\'tel-steer\').innerText = (sim.steerAngle * (180 / Math.PI)).toFixed(1);\n      document.getElementById(\'tel-dist\').innerText = sim.pos[0].toFixed(1);\n\n      const pct = Math.min(Math.round((sim.pos[0] / X_END) * 100), 100);\n      document.getElementById(\'tel-pct\').innerText = `${pct}%`;\n      document.getElementById(\'progress-fill\').style.width = `${pct}%`;\n    }\n\n    /* =========================================================================\n       10. CAMERA MODES & COCKPIT HUD\n       ========================================================================= */\n    let currentCameraMode = "cockpit";\n    let cockpitLook = { yaw: 0, pitch: 0 };\n\n    function setCameraMode(mode) {\n      currentCameraMode = mode;\n      document.querySelectorAll(\'.cam-btn\').forEach(b => b.classList.remove(\'active\'));\n      const activeBtn = document.getElementById(`btn-cam-${mode}`);\n      if (activeBtn) activeBtn.classList.add(\'active\');\n\n      const hud = document.getElementById(\'cockpit-hud\');\n      const overlay = document.getElementById(\'cockpit-overlay\');\n\n      if (mode === "cockpit") {\n        controls.enabled = false;\n        hud.style.display = \'block\';\n        overlay.style.display = \'block\';\n        toast("🏎️ Cockpit View Active. Look through the windshield with AR Telemetry!");\n      } else if (mode === "chase") {\n        controls.enabled = false;\n        hud.style.display = \'none\';\n        overlay.style.display = \'none\';\n      } else if (mode === "drone") {\n        controls.enabled = false;\n        hud.style.display = \'none\';\n        overlay.style.display = \'none\';\n      } else if (mode === "orbit") {\n        controls.enabled = true;\n        hud.style.display = \'none\';\n        overlay.style.display = \'none\';\n      } else if (mode === "tactical") {\n        controls.enabled = false;\n        hud.style.display = \'none\';\n        overlay.style.display = \'none\';\n        camera.position.set(20, 36, 0);\n        camera.lookAt(20, 0, 0);\n      }\n    }\n\n    function resetCameraOrientation() {\n      cockpitLook.yaw = 0;\n      cockpitLook.pitch = 0;\n      if (currentCameraMode === "orbit") {\n        controls.reset();\n        camera.position.set(sim.pos[0] - 8, 7, sim.pos[1] + 8);\n        controls.target.set(sim.pos[0], 0.5, sim.pos[1]);\n      }\n    }\n\n    // Cockpit Look Around with Mouse\n    window.addEventListener(\'mousemove\', (e) => {\n      if (currentCameraMode === "cockpit" && e.buttons === 1) {\n        cockpitLook.yaw -= e.movementX * 0.003;\n        cockpitLook.pitch -= e.movementY * 0.003;\n        cockpitLook.yaw = THREE.MathUtils.clamp(cockpitLook.yaw, -0.6, 0.6);\n        cockpitLook.pitch = THREE.MathUtils.clamp(cockpitLook.pitch, -0.3, 0.3);\n      }\n    });\n\n    function updateCameraRig() {\n      const carPos = carGroup.position;\n      const heading = sim.heading;\n\n      if (currentCameraMode === "cockpit") {\n        // Cockpit Camera: placed at driver\'s eye level\n        const forward = new THREE.Vector3(Math.cos(heading), 0, Math.sin(heading));\n        const right = new THREE.Vector3(-Math.sin(heading), 0, Math.cos(heading));\n\n        // Driver seat offset inside car\n        const eyePos = carPos.clone()\n          .add(forward.clone().multiplyScalar(driverSeatPos.x))\n          .add(new THREE.Vector3(0, driverSeatPos.y, 0))\n          .add(right.clone().multiplyScalar(driverSeatPos.z));\n\n        camera.position.copy(eyePos);\n\n        // Look forward through windshield with slight mouse look\n        const lookTarget = eyePos.clone()\n          .add(forward.clone().multiplyScalar(10.0))\n          .add(right.clone().multiplyScalar(cockpitLook.yaw * 8.0))\n          .add(new THREE.Vector3(0, cockpitLook.pitch * 6.0, 0));\n\n        camera.lookAt(lookTarget);\n\n      } else if (currentCameraMode === "chase") {\n        // 3rd-person Chase Camera: follows behind smoothly\n        const dist = 6.2;\n        const height = 2.6;\n        const targetCamPos = new THREE.Vector3(\n          carPos.x - Math.cos(heading) * dist,\n          height,\n          carPos.z - Math.sin(heading) * dist\n        );\n        camera.position.lerp(targetCamPos, 0.12);\n\n        const lookTarget = carPos.clone().add(new THREE.Vector3(Math.cos(heading) * 4.0, 1.0, Math.sin(heading) * 4.0));\n        camera.lookAt(lookTarget);\n\n      } else if (currentCameraMode === "drone") {\n        // 3D Drone View: overhead angle\n        const targetCamPos = new THREE.Vector3(carPos.x - 5.0, 16.0, carPos.z);\n        camera.position.lerp(targetCamPos, 0.08);\n        camera.lookAt(carPos.x + 8.0, 0, carPos.z);\n\n      } else if (currentCameraMode === "orbit") {\n        // Orbit controls track car center\n        controls.target.lerp(new THREE.Vector3(carPos.x, 0.8, carPos.z), 0.1);\n        controls.update();\n\n      } else if (currentCameraMode === "tactical") {\n        // 2D Tactical View\n        camera.position.set(20, 36, 0);\n        camera.lookAt(20, 0, 0);\n      }\n    }\n\n    /* --- 2D COCKPIT AR HUD CANVAS OVERLAY --- */\n    function renderCockpitHUD() {\n      if (currentCameraMode !== "cockpit") return;\n\n      const w = hudCanvas.width;\n      const h = hudCanvas.height;\n      hudCtx.clearRect(0, 0, w, h);\n\n      // 1. AR Target Brackets over 3D obstacles\n      obstacles.forEach(o => {\n        const obsWorld = new THREE.Vector3(o.x, 0.8, o.y);\n        const dist = Math.hypot(o.x - sim.pos[0], o.y - sim.pos[1]);\n\n        if (dist < 32 && o.x > sim.pos[0] - 1) {\n          // Project to 2D screen coordinates\n          const screenPos = obsWorld.clone().project(camera);\n          if (screenPos.z < 1) {\n            const sx = (screenPos.x * 0.5 + 0.5) * w;\n            const sy = (-screenPos.y * 0.5 + 0.5) * h;\n\n            const boxSize = Math.max(24, Math.min(100, 480 / dist));\n\n            hudCtx.strokeStyle = dist < 8 ? \'#ff3366\' : \'#00f0ff\';\n            hudCtx.lineWidth = 2;\n\n            // Corner brackets\n            const bl = boxSize * 0.25;\n            hudCtx.beginPath();\n            // Top-left\n            hudCtx.moveTo(sx - boxSize / 2, sy - boxSize / 2 + bl);\n            hudCtx.lineTo(sx - boxSize / 2, sy - boxSize / 2);\n            hudCtx.lineTo(sx - boxSize / 2 + bl, sy - boxSize / 2);\n            // Top-right\n            hudCtx.moveTo(sx + boxSize / 2 - bl, sy - boxSize / 2);\n            hudCtx.lineTo(sx + boxSize / 2, sy - boxSize / 2);\n            hudCtx.lineTo(sx + boxSize / 2, sy - boxSize / 2 + bl);\n            // Bottom-left\n            hudCtx.moveTo(sx - boxSize / 2, sy + boxSize / 2 - bl);\n            hudCtx.lineTo(sx - boxSize / 2, sy + boxSize / 2);\n            hudCtx.lineTo(sx - boxSize / 2 + bl, sy + boxSize / 2);\n            // Bottom-right\n            hudCtx.moveTo(sx + boxSize / 2 - bl, sy + boxSize / 2);\n            hudCtx.lineTo(sx + boxSize / 2, sy + boxSize / 2);\n            hudCtx.lineTo(sx + boxSize / 2, sy + boxSize / 2 - bl);\n            hudCtx.stroke();\n\n            // Distance Tag\n            hudCtx.fillStyle = \'#ffffff\';\n            hudCtx.font = \'10px Orbitron\';\n            hudCtx.fillText(`${o.type.split(\' \')[1]} ${dist.toFixed(1)}m`, sx - boxSize / 2, sy - boxSize / 2 - 6);\n          }\n        }\n      });\n\n      // 2. Windshield Speed & Autopilot Hologram (Center Bottom of glass)\n      const cx = w * 0.5;\n      const cy = h * 0.68;\n\n      hudCtx.save();\n      hudCtx.shadowColor = \'#00f0ff\';\n      hudCtx.shadowBlur = 10;\n\n      // Artificial Horizon Ladder\n      hudCtx.strokeStyle = \'rgba(0, 240, 255, 0.35)\';\n      hudCtx.lineWidth = 1.5;\n      hudCtx.beginPath();\n      hudCtx.moveTo(cx - 70, cy); hudCtx.lineTo(cx - 20, cy);\n      hudCtx.moveTo(cx + 20, cy); hudCtx.lineTo(cx + 70, cy);\n      hudCtx.stroke();\n\n      // Pitch pip\n      hudCtx.fillStyle = \'#00f0ff\';\n      hudCtx.beginPath();\n      hudCtx.arc(cx, cy, 3, 0, Math.PI * 2);\n      hudCtx.fill();\n\n      // Digital Velocity\n      hudCtx.font = \'bold 24px Orbitron\';\n      hudCtx.textAlign = \'center\';\n      hudCtx.fillText(`${sim.velocity.toFixed(1)} m/s`, cx, cy + 32);\n\n      hudCtx.font = \'11px Orbitron\';\n      hudCtx.fillStyle = \'#00ff9d\';\n      hudCtx.fillText(`⚡ FSD // ${chosenPathName}`, cx, cy + 48);\n\n      hudCtx.restore();\n    }\n\n    /* =========================================================================\n       11. INTERACTIVE 3D RAYCASTING OBSTACLE PLACEMENT\n       ========================================================================= */\n    const raycaster = new THREE.Raycaster();\n    const mouse = new THREE.Vector2();\n\n    window.addEventListener(\'click\', (e) => {\n      // Don\'t trigger if clicked on UI\n      if (e.target.closest(\'#ui-layer\')) return;\n\n      mouse.x = (e.clientX / window.innerWidth) * 2 - 1;\n      mouse.y = -(e.clientY / window.innerHeight) * 2 + 1;\n\n      raycaster.setFromCamera(mouse, camera);\n      const intersects = raycaster.intersectObject(roadMesh);\n\n      if (intersects.length > 0) {\n        const pt = intersects[0].point;\n        const placeX = Math.round(pt.x * 10) / 10;\n        const placeY = Math.round(pt.z * 10) / 10;\n\n        if (placeX < 1.0 || placeX > X_END + 2.0) {\n          toast("Please place obstacles on the active roadway (1m to 40m).");\n          return;\n        }\n        if (Math.abs(placeY) > ROAD_HALF - 0.5) {\n          toast("Please place inside the road boundaries.");\n          return;\n        }\n        if (sim.running && placeX < sim.pos[0] + 3.0) {\n          toast("⚠️ Too close to the vehicle. Drop it further ahead!");\n          return;\n        }\n\n        const newObs = makeObstacleData(selectedObstacleType, selectedObstacleMotion, placeX, placeY);\n        obstacles.push(newObs);\n        syncObstacleMeshes();\n        playChime(523, \'sine\', 0.15, 0.2);\n\n        // Visual click ripple\n        spawnRipple(placeX, placeY);\n        toast(`Dropped ${selectedObstacleType} (${selectedObstacleMotion}) at ${placeX}m`);\n\n        if (sim.running) triggerReplan();\n        else updatePathUI();\n      }\n    });\n\n    function spawnRipple(x, z) {\n      const ripGeo = new THREE.RingGeometry(0.1, 0.25, 24);\n      const ripMat = new THREE.MeshBasicMaterial({ color: 0x00f0ff, side: THREE.DoubleSide, transparent: true, opacity: 1 });\n      const rip = new THREE.Mesh(ripGeo, ripMat);\n      rip.rotation.x = -Math.PI / 2;\n      rip.position.set(x, 0.05, z);\n      scene.add(rip);\n\n      let scale = 1.0;\n      const ripInterval = setInterval(() => {\n        scale += 0.4;\n        rip.scale.set(scale, scale, scale);\n        ripMat.opacity -= 0.08;\n        if (ripMat.opacity <= 0) {\n          clearInterval(ripInterval);\n          scene.remove(rip);\n        }\n      }, 30);\n    }\n\n    function undoLastObstacle() {\n      if (obstacles.length > 0) {\n        obstacles.pop();\n        syncObstacleMeshes();\n        toast("↩️ Undid last obstacle.");\n        if (sim.running) triggerReplan();\n        else updatePathUI();\n      }\n    }\n\n    function clearAllObstacles() {\n      obstacles.length = 0;\n      syncObstacleMeshes();\n      updatePathUI();\n      hideBlockAlert();\n      toast("🗑️ Cleared all obstacles!");\n      if (sim.running) triggerReplan();\n    }\n\n    function randomizeObstacles() {\n      obstacles.length = 0;\n      const count = 5;\n      const keys = Object.keys(OBJ_PROPS);\n      const motions = ["Static", "Crossing the road", "Moving ahead"];\n\n      for (let i = 0; i < count; i++) {\n        const k = keys[Math.floor(Math.random() * keys.length)];\n        const m = motions[Math.floor(Math.random() * motions.length)];\n        const rx = Math.round((8 + Math.random() * 26) * 10) / 10;\n        const ry = Math.round((-4.2 + Math.random() * 8.4) * 10) / 10;\n        obstacles.push(makeObstacleData(k, m, rx, ry));\n      }\n      syncObstacleMeshes();\n      toast("🎲 Spawned 5 random obstacles across the highway!");\n      if (sim.running) triggerReplan();\n      else updatePathUI();\n    }\n\n    /* =========================================================================\n       12. ANIMATION LOOP & RESIZE HANDLER\n       ========================================================================= */\n    window.addEventListener(\'resize\', () => {\n      camera.aspect = window.innerWidth / window.innerHeight;\n      camera.updateProjectionMatrix();\n      renderer.setSize(window.innerWidth, window.innerHeight);\n      resizeHud();\n    });\n\n    // Keyboard Shortcuts\n    window.addEventListener(\'keydown\', (e) => {\n      if (e.key === \'1\') setCameraMode(\'cockpit\');\n      else if (e.key === \'2\') setCameraMode(\'chase\');\n      else if (e.key === \'3\') setCameraMode(\'drone\');\n      else if (e.key === \'4\') setCameraMode(\'orbit\');\n      else if (e.key === \'5\') setCameraMode(\'tactical\');\n      else if (e.code === \'Space\') { e.preventDefault(); toggleDrive(); }\n      else if (e.key === \'r\' || e.key === \'R\') resetSimulation();\n    });\n\n    // Main 60 FPS Render Loop\n    function animate() {\n      requestAnimationFrame(animate);\n\n      stepWorld();\n      updateCameraRig();\n      renderer.render(scene, camera);\n      renderCockpitHUD();\n    }\n\n    // Initialize\n    updatePathUI();\n    randomizeObstacles();\n    setCameraMode("cockpit");\n    animate();\n\n  </script>\n</body>\n</html>\n'

"""
Smart Autonomous Vehicle Path Planner & 3D Cockpit Simulator

Features:
- Real-time 3D WebGL Frontend with multiple camera views:
  * 🏎️ Cockpit View (First-Person Driver POV) with steering wheel animation & AR windshield HUD
  * 🎥 Chase Cam (Smooth 3rd-person follow)
  * 🚁 Drone View (High-angle tactical overhead)
  * 🌐 Free 3D Orbit (Full 360° mouse inspection)
  * 🗺️ 2D Tactical LiDAR (Top-down precision map)
- Interactive 3D obstacle placement: click directly on the road while driving!
- Moving obstacle physics with velocity vectors & edge bouncing
- Time-aware A* neural path planning with dynamic re-routing & safe gap waiting
- 2D & 3D synchronized telemetry & analysis
"""
